        font-weight: 900 !important;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        position: relative;
        overflow: hidden;
        transition: transform 0.16s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.16s ease, border-color 0.16s ease !important;
        will-change: transform;
        cursor: pointer;
    }
    #split-invoice-view button.kinetic-mini-step-btn {
        min-height: 32px !important;
        width: 32px !important;
        padding: 0 !important;
        border-radius: 8px !important;
    }

    /* شارات اختصارات لوحة المفاتيح المصغرة على الأزرار الرئيسية */
    .c3-kbd {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 1px 6px;
        font-size: 0.7rem;
        font-family: 'Outfit', monospace;
        font-weight: 900;
        border-radius: 5px;
        background: rgba(0, 0, 0, 0.35);
        color: #ffffff !important;
        -webkit-text-fill-color: #ffffff !important;
        border: 1px solid rgba(255, 255, 255, 0.35);
        line-height: 1.2;
        pointer-events: none;
    }
    :root.light-theme .c3-kbd {
        background: rgba(15, 23, 42, 0.12);
