<script id="split-constitution7-foundations-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION7_LOCK__) return;
    window.__SPLIT_CONSTITUTION7_LOCK__ = true;

    const arabicDigitsMap = {
        '٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9',
        '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9'
    };

    // دالة التطبيع الفوري للأرقام (العربية/الفارسية -> الإنجليزية) والفاصلة العشرية (و / ، / , / ٫ -> .) مع دعم الآلة الحاسبة المدمجة (+ - * / ( ))
    window.normalizeSplitNumericString = function(rawVal, allowDecimal, allowMath) {
        if (rawVal === null || rawVal === undefined) return '';
        if (allowMath === undefined) allowMath = true;
        let s = String(rawVal)
            // إزالة الحروف الخفية وحروف التحكم من واتساب وإكسل
            .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
            // تحويل الأرقام العربية والفارسية إلى إنجليزية
            .replace(/[٠-٩۰-۹]/g, function(d) { return arabicDigitsMap[d] || d; })
            // تحويل رموز الضرب والقسمة إلى قياسية
            .replace(/[×✕]/g, '*')
            .replace(/[÷]/g, '/')
            // تحويل مفاتيح الفاصلة العربية والإنجليزية (و، ،، ,، ٫، ٬) إلى نقطة عشرية قياسية
            .replace(/[و،,٫٬]/g, '.');

        if (!allowDecimal) {
            return allowMath ? s.replace(/[^0-9+\-*/()]/g, '') : s.replace(/[^0-9]/g, '');
        }
        if (allowMath && /[+\-*/()]/.test(s)) {
            return s.replace(/[^0-9.+\-*/()]/g, '');
        }
        // إبقاء الأرقام والنقطة العشرية فقط مع منع تكرار النقطة العشرية
        s = s.replace(/[^0-9.]/g, '');
        const parts = s.split('.');
        if (parts.length > 2) {
            s = parts[0] + '.' + parts.slice(1).join('');
        }
        return s;
    };

    // دالة تنظيف النصوص من الحروف الخفية والمسافات الزائدة
    window.cleanSplitTextValue = function(rawVal, trimEdges) {
        let s = String(rawVal ?? '')
            .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
            .replace(/[٠-٩۰-۹]/g, function(d) { return arabicDigitsMap[d] || d; })
            .replace(/\s{2,}/g, ' ');
        return trimEdges ? s.trim() : s;
    };

    function isSplitNumericInput(el) {
        if (!el || el.tagName !== 'INPUT') return false;
        const id = el.id || '';
        return id.indexOf('split-qty-') === 0 || id.indexOf('split-subqty-') === 0 || id === 'split-operation-seq-input';
    }

    // 1. اعتراض الكتابة الفورية في خانات الأرقام والكميات لتحويل الأرقام العربية والفاصلة (و / ، / ,) في نفس اللحظة
    document.addEventListener('input', function(e) {
        const el = e.target;
        if (!el || !el.closest || !el.closest('#split-invoice-view')) return;

        if (isSplitNumericInput(el)) {
            const allowDec = el.id !== 'split-operation-seq-input';
            const cleaned = window.normalizeSplitNumericString(el.value, allowDec);
            if (el.value !== cleaned) {
                const pos = el.selectionStart;
                el.value = cleaned;
                try {
                    if (typeof pos === 'number') el.setSelectionRange(pos, pos);
                } catch (err) {}
            }
        } else if (el.tagName === 'INPUT' && el.type === 'text') {
            const cleaned = window.cleanSplitTextValue(el.value, false);
            if (el.value !== cleaned) {
                el.value = cleaned;
            }
        }
    }, true);

    // 2. التنظيف التلقائي للمسافات الزائدة (Auto-Trim) عند الخروج من الخانة (blur / change)
    document.addEventListener('change', function(e) {
        const el = e.target;
        if (!el || el.tagName !== 'INPUT' || !el.closest || !el.closest('#split-invoice-view')) return;
        if (!isSplitNumericInput(el) && el.type === 'text') {
            const trimmed = window.cleanSplitTextValue(el.value, true);
            if (el.value !== trimmed) {
                el.value = trimmed;
                el.dispatchEvent(new Event('input', { bubbles: true }));
            }
        }
    }, true);

    // 3. اللصق الذكي النظيف (Smart Paste Ctrl+V) من واتساب أو إكسل مع تصفية العملات والفواصل
    document.addEventListener('paste', function(e) {
        const el = e.target;
        if (!el || el.tagName !== 'INPUT' || !el.closest || !el.closest('#split-invoice-view')) return;
        const clip = (e.clipboardData || window.clipboardData);
        if (!clip) return;
        const pastedText = clip.getData('text');
        if (!pastedText) return;

        e.preventDefault();
        if (isSplitNumericInput(el)) {
            if (typeof window.pushSplitUndoSnapshot === 'function') window.pushSplitUndoSnapshot();
            // إزالة فواصل الآلاف إذا كانت متبوعة بـ 3 أرقام مثل 12,500 ثم تطبيع الأرقام والفاصلة العشرية
            let preCleaned = String(pastedText)
                .replace(/[٠-٩۰-۹]/g, function(d) { return arabicDigitsMap[d] || d; })
                .replace(/(\d),(?=\d{3}(\D|$))/g, '$1');
            const allowDec = el.id !== 'split-operation-seq-input';
            const cleanNum = window.normalizeSplitNumericString(preCleaned, allowDec);
            el.value = cleanNum || '0';
            el.dispatchEvent(new Event('input', { bubbles: true }));
            if (typeof showToast === 'function') {
                showToast('📋 تم اللصق الذكي وتصفية الرقم تلقائياً: ' + el.value, 'info');
            }
        } else {
            const cleanTxt = window.cleanSplitTextValue(pastedText, true);
            el.value = cleanTxt;
            el.dispatchEvent(new Event('input', { bubbles: true }));
        }
    }, true);

    // 4. منظومة التراجع الفوري المتعدد (Ctrl + Z) + زر التصفير وإعادة الضبط
    window._splitUndoHistoryStack = [];

    window.captureSplitStateObject = function() {
        if (!window.activeSplitInvoice) return null;
        if (typeof window.saveCurrentSplitDraftState === 'function') {
            window.saveCurrentSplitDraftState();
        }
        return {
            invoiceNo: String(window.activeSplitInvoice.invoiceNo || window.activeSplitInvoice.id || ''),
            sectionsCount: window.splitSectionsCount || 2,
            splitSeq: window.currentSplitOperationSeq || 1,
            unitMode: window.splitUnitDisplayMode || 'both',
            qtys: JSON.parse(JSON.stringify(window.activeSplitInvoice._splitDraftQtys || {})),
            meta: JSON.parse(JSON.stringify(window._splitSectionMeta || {}))
        };
    };

    window.pushSplitUndoSnapshot = function() {
        const snap = window.captureSplitStateObject();
        if (!snap) return;
        const stack = window._splitUndoHistoryStack;
        const last = stack.length ? stack[stack.length - 1] : null;
        if (last && JSON.stringify(last.qtys) === JSON.stringify(snap.qtys) && last.sectionsCount === snap.sectionsCount && JSON.stringify(last.meta) === JSON.stringify(snap.meta)) {
            return;
        }
        stack.push(snap);
        if (stack.length > 30) stack.shift();
    };

    // حفظ لقطة قبل تعديل أي خانة كمية عند التركيز عليها (focusin)
    document.addEventListener('focusin', function(e) {
        const el = e.target;
        if (el && el.closest && el.closest('#split-board-step') && el.tagName === 'INPUT') {
            window.pushSplitUndoSnapshot();
        }
    }, true);

    window.undoLastSplitChange = function() {
        if (!window.activeSplitInvoice) return;
        const stack = window._splitUndoHistoryStack || [];
        const currentSnap = window.captureSplitStateObject();
        let targetSnap = null;
        while (stack.length > 0) {
            const candidate = stack.pop();
            if (!currentSnap || candidate.invoiceNo !== currentSnap.invoiceNo) continue;
            if (JSON.stringify(candidate.qtys) !== JSON.stringify(currentSnap.qtys) ||
                candidate.sectionsCount !== currentSnap.sectionsCount ||
                JSON.stringify(candidate.meta) !== JSON.stringify(currentSnap.meta)) {
                targetSnap = candidate;
                break;
            }
        }
        if (!targetSnap) {
            if (typeof showToast === 'function') showToast('ℹ️ لا توجد خطوة سابقة للتراجع عنها', 'info');
            return;
        }
        window.splitSectionsCount = targetSnap.sectionsCount || 2;
        window.currentSplitOperationSeq = targetSnap.splitSeq || 1;
        window.splitUnitDisplayMode = targetSnap.unitMode || 'both';
        window.activeSplitInvoice._splitDraftQtys = JSON.parse(JSON.stringify(targetSnap.qtys));
        window._splitSectionMeta = JSON.parse(JSON.stringify(targetSnap.meta));
        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        if (typeof window.autoFitSplitInputs === 'function') {
            window.autoFitSplitInputs();
        }
        if (typeof showToast === 'function') {
            showToast('↩️ تم التراجع واستعادة الخطوة السابقة بنجاح (Ctrl+Z)', 'success');
        }
    };

    window.resetCurrentSplitBoard = function() {
        if (!window.activeSplitInvoice) return;
        window.pushSplitUndoSnapshot();
        window.splitSectionsCount = 2;
        window._splitSectionMeta = {};
        window.activeSplitInvoice._splitDraftQtys = {};
        (window.activeSplitInvoice.items || []).forEach(function(item, idx) {
            const meta = window.resolveSplitItemUnitMeta(item);
            const rem = meta.deliverableQty;
            let q1 = rem > 1 ? Math.ceil(rem / 2) : +(rem / 2).toFixed(3);
            if (rem === 5) q1 = 3;
            let q2 = Math.max(0, +(rem - q1).toFixed(4));
            window.activeSplitInvoice._splitDraftQtys[idx] = [q1, q2];
        });
        if (typeof window.clearSplitCrashVaultForInvoice === 'function') {
            window.clearSplitCrashVaultForInvoice(window.activeSplitInvoice.invoiceNo || window.activeSplitInvoice.id);
        }
        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        if (typeof window.autoFitSplitInputs === 'function') {
            window.autoFitSplitInputs();
        }
        if (typeof showToast === 'function') {
            showToast('🧹 تم تصفير وإعادة ضبط توزيع الفاتورة (يمكنك التراجع بـ Ctrl+Z)', 'info');
        }
    };

    // اختصار الكيبورد العالمي (Ctrl+Z) داخل شاشة التقسيم
    document.addEventListener('keydown', function(e) {
        const splitView = document.getElementById('split-invoice-view');
        if (!splitView || splitView.style.display === 'none') return;
        if ((e.ctrlKey || e.metaKey) && (e.key === 'z' || e.key === 'Z' || e.key === 'ئ') && !e.shiftKey) {
            if (window.activeSplitInvoice) {
                e.preventDefault();
                window.undoLastSplitChange();
            }
        }
    });

    // 5. دعم قارئ الباركود السريع (Barcode Scanner Support) لفتح الفاتورة أو التركيز على الصنف تلقائياً
    let barcodeBuffer = '';
    let lastBarcodeKeyTime = 0;
    document.addEventListener('keydown', function(e) {
        const splitView = document.getElementById('split-invoice-view');
        if (!splitView || splitView.style.display === 'none') return;
        const activeTag = document.activeElement ? document.activeElement.tagName : '';
        if (activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT') return;

        const now = performance.now();
        if (now - lastBarcodeKeyTime > 85) {
            barcodeBuffer = '';
        }
        lastBarcodeKeyTime = now;

        if (e.key === 'Enter' && barcodeBuffer.length >= 3) {
            e.preventDefault();
            const scannedCode = window.cleanSplitTextValue(barcodeBuffer, true);
            barcodeBuffer = '';
            if (!window.activeSplitInvoice) {
                const searchInp = document.getElementById('split-invoice-search');
                if (searchInp) {
                    searchInp.value = scannedCode;
                    if (typeof filterSplitInvoices === 'function') filterSplitInvoices();
                    const firstSplitBtn = document.querySelector('#split-invoices-list button[onclick*="prepareInvoiceForSplit"]');
                    if (firstSplitBtn) firstSplitBtn.click();
                }
            } else {
                const items = window.activeSplitInvoice.items || [];
                const foundIdx = items.findIndex(function(it) {
                    return String(it.barcode || it.itemCode || it.id || it.name || '').toLowerCase().indexOf(scannedCode.toLowerCase()) !== -1;
                });
                if (foundIdx !== -1) {
                    const qtyInp = document.getElementById('split-qty-s0-i' + foundIdx);
                    if (qtyInp) {
                        qtyInp.focus();
                        if (qtyInp.select) try { qtyInp.select(); } catch (err) {}
                        if (typeof showToast === 'function') showToast('🔫 تم تحديد الصنف بالباركود: ' + (items[foundIdx].name || scannedCode), 'success');
                    }
                }
            }
        } else if (e.key && e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {
            barcodeBuffer += e.key;
        }
    });

    // 6. تحديث مؤشر الاتصال والمزامنة المطمئن لحظياً
    function updateSplitConnectionIndicator() {
        const badge = document.getElementById('split-c7-conn-badge');
        const dot = document.getElementById('split-c7-conn-dot');
        const txt = document.getElementById('split-c7-conn-text');
        if (!badge || !dot || !txt) return;
        const online = navigator.onLine !== false;
        if (online) {
            badge.style.borderColor = '#10b981';
            badge.style.background = 'rgba(16,185,129,0.14)';
            dot.style.background = '#10b981';
            dot.style.boxShadow = '0 0 8px #10b981';
            txt.textContent = 'متصل ومتزامن';
        } else {
            badge.style.borderColor = '#f59e0b';
            badge.style.background = 'rgba(245,158,11,0.16)';
            dot.style.background = '#f59e0b';
            dot.style.boxShadow = '0 0 8px #f59e0b';
            txt.textContent = 'أوفلاين (محفوظ محلياً)';
        }
    }
    window.addEventListener('online', updateSplitConnectionIndicator);
    window.addEventListener('offline', updateSplitConnectionIndicator);
    document.addEventListener('DOMContentLoaded', updateSplitConnectionIndicator);
    setTimeout(updateSplitConnectionIndicator, 150);
})();
</script>
<style id="split-constitution8-cognitive-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور الثامن (8 من 14): علم النفس المعرفي، الآلة الحاسبة المدمجة، التفقيط، حارس الأرقام الشاذة، ونفق التركيز
       ═══════════════════════════════════════════════════════════════════════════ */

    /* 1. حارس الإرهاق الذكي للأرقام الشاذة وأخطاء الأصابع (Pulsing Amber Cognitive Guard) */
    @keyframes c8AmberPulseGuard {
        0%, 100% { box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.55), 0 0 18px rgba(245, 158, 11, 0.45); border-color: #f59e0b !important; }
        50% { box-shadow: 0 0 0 6px rgba(251, 191, 36, 0.75), 0 0 26px rgba(245, 158, 11, 0.7); border-color: #fbbf24 !important; }
    }
    .c8-anomaly-amber-pulse {
        animation: c8AmberPulseGuard 0.9s ease-in-out 3 !important;
        border: 2.5px solid #f59e0b !important;
    }

    /* 2. نفق التركيز البصري (Optical Focus Tunnel) لتهدئة السطور البعيدة وتركيز عين المحاسب على السطر النشط */
    #split-board-step table.pos-grid tbody:focus-within tr:not(:focus-within):not(:hover) {
        opacity: 0.76;
        transition: opacity 0.18s ease !important;
    }
    #split-board-step table.pos-grid tbody:focus-within tr:focus-within {
        opacity: 1 !important;
    }

    /* 3. تنسيق سطر التفقيط العربي اللحظي في الثيم الداكن والفاتح */
    .c8-tafqeet-line {
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
        letter-spacing: 0;
    }
    :root.light-theme .c8-tafqeet-line {
        background: #d1fae5 !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border-color: #047857 !important;
        font-weight: 900 !important;
    }
    :root.light-theme #split-parked-vouchers-bar {
        background: #fef3c7 !important;
        border: 2.2px solid #b45309 !important;
        color: #000000 !important;
    }
</style>

<script id="split-constitution8-cognitive-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION8_LOCK__) return;
    window.__SPLIT_CONSTITUTION8_LOCK__ = true;

    const PARKED_KEY = 'erp_split_parked_vouchers_v1';
    const RECENT_COMMITS_KEY = 'erp_split_recent_commits_v1';

    // 1. الآلة الحاسبة المدمجة داخل الخانات الرقمية (Inline Math Calculator: 12*24, 5000+1500, 100/4)
    window.evalSplitInlineMath = function(rawExpr) {
        if (rawExpr === null || rawExpr === undefined) return 0;
        let s = String(rawExpr).trim();
        if (!s) return 0;
        if (window.normalizeSplitNumericString) {
            s = window.normalizeSplitNumericString(s, true, true);
        }
        // إزالة أي عامل حسابي في آخر النص أثناء الكتابة الحية مثل "12*" -> "12"
        const cleanForLive = s.replace(/[+\-*/.(]+$/, '');
        if (!cleanForLive) return 0;
        if (!/^[0-9.+\-*/()\s]+$/.test(cleanForLive)) {
            return parseFloat(cleanForLive) || 0;
        }
        try {
            const val = Function('"use strict"; return (' + cleanForLive + ');')();
            if (typeof val === 'number' && isFinite(val)) {
                return +val.toFixed(4);
            }
        } catch (err) {}
        return parseFloat(cleanForLive) || 0;
    };

    window.commitSplitInlineMathInput = function(el) {
        if (!el || el.tagName !== 'INPUT') return false;
        const id = el.id || '';
        if (id.indexOf('split-qty-') !== 0 && id.indexOf('split-subqty-') !== 0 && id !== 'split-operation-seq-input') return false;
        const raw = String(el.value || '').trim();
        if (!/[+\-*/()]/.test(raw)) return false;

        const evaluated = window.evalSplitInlineMath(raw);
        const finalVal = id === 'split-operation-seq-input' ? Math.max(1, Math.round(evaluated)) : Math.max(0, evaluated);
        el.value = String(finalVal);
        el.dispatchEvent(new Event('input', { bubbles: true }));
        if (typeof showToast === 'function') {
            showToast('🧮 الآلة الحاسبة المدمجة: ' + raw + ' = ' + finalVal, 'info');
        }
        return true;
    };

    // تنفيذ المعادلة الحسابية لحظة ضغط Enter أو الخروج من الخانة (blur)
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && e.target && e.target.closest && e.target.closest('#split-invoice-view')) {
            window.commitSplitInlineMathInput(e.target);
        }
    }, true);

    document.addEventListener('blur', function(e) {
        if (e.target && e.target.closest && e.target.closest('#split-invoice-view')) {
            window.commitSplitInlineMathInput(e.target);
        }
    }, true);

    // 2. محرك التفقيط العربي اللحظي المعتمد لمنع خداع الأصفار (Instant Amount-in-Words)
    const onesAr = ['', 'واحد', 'اثنان', 'ثلاثة', 'أربعة', 'خمسة', 'ستة', 'سبعة', 'ثمانية', 'تسعة', 'عشرة', 'أحد عشر', 'اثنا عشر', 'ثلاثة عشر', 'أربعة عشر', 'خمسة عشر', 'ستة عشر', 'سبعة عشر', 'ثمانية عشر', 'تسعة عشر'];
    const tensAr = ['', 'عشرة', 'عشرون', 'ثلاثون', 'أربعون', 'خمسون', 'ستون', 'سبعون', 'ثمانون', 'تسعون'];
    const hundredsAr = ['', 'مائة', 'مائتان', 'ثلاثمائة', 'أربعمائة', 'خمسمائة', 'ستمائة', 'سبعمائة', 'ثمانمائة', 'تسعمائة'];

    function convertThreeDigitsAr(n) {
        n = Math.floor(n % 1000);
        if (n === 0) return '';
        const h = Math.floor(n / 100);
        const rem = n % 100;
        const parts = [];
        if (h > 0) parts.push(hundredsAr[h]);
        if (rem > 0) {
            if (rem < 20) {
                parts.push(onesAr[rem]);
            } else {
                const u = rem % 10;
                const t = Math.floor(rem / 10);
                if (u > 0) parts.push(onesAr[u] + ' و' + tensAr[t]);
                else parts.push(tensAr[t]);
            }
        }
        return parts.join(' و');
    }

    function convertIntegerToArabicWords(num) {
        num = Math.floor(Math.abs(Number(num) || 0));
        if (num === 0) return 'صفر';
        const groups = [
            { scale: 1000000000, single: 'مليار', dual: 'ملياران', plural: 'مليارات', acc: 'ملياراً' },
            { scale: 1000000, single: 'مليون', dual: 'مليونان', plural: 'ملايين', acc: 'مليوناً' },
            { scale: 1000, single: 'ألف', dual: 'ألفان', plural: 'آلاف', acc: 'ألفاً' }
        ];
        const parts = [];
        let rem = num;
        for (let i = 0; i < groups.length; i++) {
            const g = groups[i];
            const count = Math.floor(rem / g.scale);
            rem = rem % g.scale;
            if (count > 0) {
                if (count === 1) parts.push(g.single);
                else if (count === 2) parts.push(g.dual);
                else if (count >= 3 && count <= 10) parts.push(convertThreeDigitsAr(count) + ' ' + g.plural);
                else parts.push(convertThreeDigitsAr(count) + ' ' + g.acc);
            }
        }
        if (rem > 0) {
            parts.push(convertThreeDigitsAr(rem));
        }
        return parts.join(' و');
    }

    window.tafqeetSplitAmountArabic = function(amount, currencyCode) {
        const val = Math.max(0, Number(amount) || 0);
        const intPart = Math.floor(val);
        const decPart = Math.round((val - intPart) * 100);
        const isUsd = String(currencyCode || '').toUpperCase() === 'USD' || String(currencyCode || '').indexOf('$') !== -1;
        const curName = isUsd ? 'دولار أمريكي' : 'جنيه سوداني';
        const subCurName = isUsd ? 'سنت' : 'قرش';

        let words = 'فقط ' + convertIntegerToArabicWords(intPart) + ' ' + curName;
        if (decPart > 0) {
            words += ' و' + convertIntegerToArabicWords(decPart) + ' ' + subCurName;
        }
        return words + ' لا غير';
    };

    // 3. حارس الإرهاق الذكي لكشف الأرقام الشاذة وأخطاء الأصابع (Fat-Finger Anomaly Guard)
    let lastAnomalyToastAt = 0;
    window.triggerSplitFatFingerAnomaly = function(inputEl, typedVal, maxAllowed, unitLabel) {
        if (inputEl) {
            inputEl.classList.remove('c8-anomaly-amber-pulse');
            void inputEl.offsetWidth;
            inputEl.classList.add('c8-anomaly-amber-pulse');
            setTimeout(function() {
                inputEl.classList.remove('c8-anomaly-amber-pulse');
            }, 2800);
        }
        const now = Date.now();
        if (now - lastAnomalyToastAt > 1800 && typeof showToast === 'function') {
            lastAnomalyToastAt = now;
            showToast(`🛡️ تنبيه تركيز: الرقم المدخل (${typedVal}) يتجاوز المتاح (${maxAllowed} ${unitLabel || ''}) — تم ضبطه للحد الأقصى`, 'warning');
        }
    };

    // 4. ميزة "تعليق الفاتورة بضغطة زر" واسترجاعها (One-Click Park & Resume)
    window.getParkedSplitVouchers = function() {
        try {
            return JSON.parse(localStorage.getItem(PARKED_KEY) || '[]') || [];
        } catch (e) { return []; }
    };

    window.renderParkedSplitVouchersBar = function() {
        const bar = document.getElementById('split-parked-vouchers-bar');
        if (!bar) return;
        const list = window.getParkedSplitVouchers();
        if (!list.length) {
            bar.style.display = 'none';
            bar.innerHTML = '';
            return;
        }
        bar.style.display = 'flex';
        const pillsHtml = list.map(function(p) {
            const escNo = String(p.invoiceNo).replace(/'/g, "\\'");
            return `<div style="display:inline-flex; align-items:center; gap:6px; background:rgba(2,6,23,0.82); border:1.8px solid #f59e0b; padding:4px 10px; border-radius:99px; font-size:0.8rem; font-weight:900; color:#fde68a;">
                <button type="button" onclick="window.resumeParkedSplitInvoice('${escNo}')" style="background:transparent; border:none !important; min-height:auto !important; padding:0 !important; color:#fde68a; font-weight:900; cursor:pointer; box-shadow:none !important;">
                    ▶️ استئناف #${p.invoiceNo} (${p.customerName || 'عميل نقدي'} • ${p.sectionsCount || 2} أقسام)
                </button>
                <button type="button" onclick="window.removeParkedSplitInvoiceByNo('${escNo}')" title="إزالة من المعلقات" style="background:rgba(239,68,68,0.25); border:1px solid #ef4444 !important; min-height:22px !important; width:22px !important; padding:0 !important; border-radius:50% !important; color:#fca5a5; font-size:0.72rem; cursor:pointer;">✕</button>
            </div>`;
        }).join('');

        bar.innerHTML = `
            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                <span style="font-weight:900; font-size:0.85rem; color:#fbbf24;">⏸️ فواتير معلقة بانتظار الاستكمال (${list.length}):</span>
                ${pillsHtml}
            </div>
        `;
    };

    window.parkCurrentSplitInvoice = function() {
        if (!window.activeSplitInvoice) {
            if (typeof showToast === 'function') showToast('ℹ️ لا توجد فاتورة مفتوحة حالياً لتعليقها', 'info');
            return;
        }
        if (typeof window.saveCurrentSplitDraftState === 'function') {
            window.saveCurrentSplitDraftState();
        }
        if (typeof window.persistActiveSplitDraftToStorage === 'function') {
            window.persistActiveSplitDraftToStorage();
        }
        const inv = window.activeSplitInvoice;
        const invNo = String(inv.invoiceNo || inv.id || '');
        const list = window.getParkedSplitVouchers().filter(function(x) { return String(x.invoiceNo) !== invNo; });
        list.unshift({
            invoiceNo: invNo,
            customerName: inv.customerName || 'عميل نقدي',
            grandTotal: parseFloat(inv.grandTotal || inv.total || 0) || 0,
            currency: inv.currency || 'SDG',
            sectionsCount: window.splitSectionsCount || 2,
            splitSeq: window.currentSplitOperationSeq || 1,
            unitMode: window.splitUnitDisplayMode || 'both',
            qtys: JSON.parse(JSON.stringify(inv._splitDraftQtys || {})),
            meta: JSON.parse(JSON.stringify(window._splitSectionMeta || {})),
            parkedAt: Date.now()
        });
        localStorage.setItem(PARKED_KEY, JSON.stringify(list.slice(0, 15)));

        window.activeSplitInvoice = null;
        if (typeof activeSplitInvoice !== 'undefined') activeSplitInvoice = null;
        const boardStep = document.getElementById('split-board-step');
        const selectStep = document.getElementById('split-select-step');
        if (boardStep) boardStep.style.display = 'none';
        if (selectStep) selectStep.style.display = 'block';
        window.renderParkedSplitVouchersBar();
        if (typeof loadSplitInvoices === 'function') loadSplitInvoices(true);
        const searchInp = document.getElementById('split-invoice-search');
        if (searchInp) {
            searchInp.focus();
            if (searchInp.select) try { searchInp.select(); } catch (e) {}
        }
        if (typeof showToast === 'function') {
            showToast(`⏸️ تم تعليق تقسيم الفاتورة #${invNo} مؤقتاً في الشريط العلوي لخدمة العميل التالي`, 'success');
        }
    };

    window.resumeParkedSplitInvoice = function(invoiceNo) {
        const list = window.getParkedSplitVouchers();
        const found = list.find(function(x) { return String(x.invoiceNo) === String(invoiceNo); });
        if (typeof prepareInvoiceForSplit === 'function') {
            prepareInvoiceForSplit(invoiceNo, found ? found.unitMode : undefined);
        }
        if (found && window.activeSplitInvoice) {
            window.splitSectionsCount = found.sectionsCount || 2;
            window.currentSplitOperationSeq = found.splitSeq || window.currentSplitOperationSeq || 1;
            window.activeSplitInvoice._splitDraftQtys = JSON.parse(JSON.stringify(found.qtys || {}));
            window._splitSectionMeta = JSON.parse(JSON.stringify(found.meta || {}));
            if (typeof window.renderWorldClassSplitBoard === 'function') {
                window.renderWorldClassSplitBoard();
            }
            if (typeof window.autoFitSplitInputs === 'function') {
                window.autoFitSplitInputs();
            }
        }
        window.renderParkedSplitVouchersBar();
        if (typeof showToast === 'function') {
            showToast(`▶️ تم استرجاع الفاتورة المعلقة #${invoiceNo} بكامل بياناتها وتوزيعاتها`, 'success');
        }
    };

    window.removeParkedSplitInvoiceByNo = function(invoiceNo) {
        const list = window.getParkedSplitVouchers().filter(function(x) { return String(x.invoiceNo) !== String(invoiceNo); });
        localStorage.setItem(PARKED_KEY, JSON.stringify(list));
        window.renderParkedSplitVouchersBar();
    };

    // اختصار Alt+P لتعليق الفاتورة فوراً بالكيبورد
    document.addEventListener('keydown', function(e) {
        const splitView = document.getElementById('split-invoice-view');
        if (!splitView || splitView.style.display === 'none') return;
        if (e.altKey && (e.key === 'p' || e.key === 'P' || e.key === 'ح') && window.activeSplitInvoice) {
            e.preventDefault();
            window.parkCurrentSplitInvoice();
        }
    });

    // 5. رادار منع تكرار نفس الفاتورة أو التقسيم بالخطأ في نفس اليوم (Anti-Duplicate Transaction Guard)
    function buildSplitFingerprint(inv, sectionItems, S) {
        const cust = String(inv.customerName || inv.customer || 'walk-in').trim();
        const grand = +(parseFloat(inv.grandTotal || inv.total || 0)).toFixed(2);
        const secSig = (sectionItems || []).map(function(arr) {
            return (arr || []).map(function(it) { return (it.itemId || it.name) + ':' + (+parseFloat(it.qty || it.quantity || 0).toFixed(3)); }).join(',');
        }).join('|');
        return cust + '||' + grand + '||' + S + '||' + secSig;
    }

    window.checkSplitDuplicateTransactionGuard = function(inv, sectionItems, S) {
        try {
            const fp = buildSplitFingerprint(inv, sectionItems, S);
            const todayStr = new Date().toISOString().slice(0, 10);
            const commits = JSON.parse(localStorage.getItem(RECENT_COMMITS_KEY) || '[]') || [];
            const match = commits.find(function(c) {
                return c.date === todayStr && c.fingerprint === fp && (Date.now() - (c.timestamp || 0)) < 12 * 3600 * 1000;
            });
            return match || null;
        } catch (e) { return null; }
    };

    window.recordSplitCommitForDuplicateGuard = function(inv, sectionItems, S, refVoucherNo) {
        try {
            const fp = buildSplitFingerprint(inv, sectionItems, S);
            const todayStr = new Date().toISOString().slice(0, 10);
            const commits = (JSON.parse(localStorage.getItem(RECENT_COMMITS_KEY) || '[]') || []).slice(0, 40);
            commits.unshift({
                fingerprint: fp,
                voucherNo: refVoucherNo,
                customerName: inv.customerName || 'عميل نقدي',
                date: todayStr,
                timestamp: Date.now()
            });
            localStorage.setItem(RECENT_COMMITS_KEY, JSON.stringify(commits));
        } catch (e) {}
    };

    window.showSplitDuplicateGuardModal = function(dupInfo, autoPrintVouchers) {
        let modal = document.getElementById('split-c8-duplicate-guard-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-c8-duplicate-guard-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:flex; position:fixed; inset:0; background:rgba(2,6,23,0.82); z-index:999980; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        modal.style.display = 'flex';
        modal.innerHTML = `
            <div class="modal-card" style="max-width:520px; width:100%; background:#0f172a; border:2.5px solid #f59e0b; border-radius:18px; padding:22px; box-shadow:0 20px 50px rgba(0,0,0,0.65); text-align:center;">
                <div style="font-size:2.4rem; margin-bottom:8px;">🛡️</div>
                <h3 style="margin:0 0 10px; color:#fbbf24; font-size:1.18rem; font-weight:900;">تنبيه تركيز: منع تكرار الحركة بالسهو</h3>
                <p style="margin:0 0 18px; color:#f8fafc; font-size:0.95rem; font-weight:800; line-height:1.65;">
                    تنبيه تركيز: توجد حركة مطابقة تماماً تم حفظها لهذا العميل (${dupInfo.customerName || 'عميل نقدي'}) قبل قليل برقم (<strong style="color:#38bdf8; font-family:monospace;">#${dupInfo.voucherNo}</strong>)، هل أنت متأكد من تكرارها؟
                </p>
                <div style="display:flex; align-items:center; justify-content:center; gap:10px; flex-wrap:wrap;">
                    <button type="button" onclick="document.getElementById('split-c8-duplicate-guard-modal').style.display='none';" class="btn-action" style="width:auto; padding:8px 20px; border-radius:10px; background:rgba(16,185,129,0.2); border:2px solid #10b981; color:#6ee7b7; font-weight:900; cursor:pointer;">🛑 لا، إيقاف التكرار</button>
                    <button type="button" onclick="document.getElementById('split-c8-duplicate-guard-modal').style.display='none'; window._bypassSplitDuplicateConfirmOnce=true; submitInvoiceSplit(${autoPrintVouchers ? 'true' : 'false'});" class="btn-action" style="width:auto; padding:8px 18px; border-radius:10px; background:rgba(245,158,11,0.2); border:2px solid #f59e0b; color:#fde68a; font-weight:900; cursor:pointer;">✅ نعم، متأكد من الحفظ</button>
                </div>
            </div>
        `;
    };

    document.addEventListener('DOMContentLoaded', function() {
        window.renderParkedSplitVouchersBar();
    });
    setTimeout(window.renderParkedSplitVouchersBar, 200);
})();
</script>
<style id="split-constitution9-wms-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور التاسع (9 من 14): العمق المخزني، تعدد الوحدات، الاستلام الجزئي، وشاشة "فحص واستلام" والفرز
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-inspection-sorting-modal .modal-card,
    #split-warehouse-transfer-modal .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-inspection-sorting-modal .modal-card,
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-warehouse-transfer-modal .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #38bdf8 !important;
    }
    :root.light-theme #split-inspection-sorting-modal .modal-card,
    :root.light-theme #split-warehouse-transfer-modal .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-inspection-sorting-modal input,
    :root.light-theme #split-inspection-sorting-modal select,
    :root.light-theme #split-warehouse-transfer-modal input,
    :root.light-theme #split-warehouse-transfer-modal select {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #0f172a !important;
        font-weight: 900 !important;
    }
</style>

<script id="split-constitution9-wms-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION9_LOCK__) return;
    window.__SPLIT_CONSTITUTION9_LOCK__ = true;

    // 1. التعديل اللحظي لمعامل تحويل الوحدات (Multi-Unit Auto-Conversion Factor)
    window.promptSplitUnitFactorChange = function(itemIdx) {
        if (!window.activeSplitInvoice || !window.activeSplitInvoice.items[itemIdx]) return;
        const item = window.activeSplitInvoice.items[itemIdx];
        const meta = window.resolveSplitItemUnitMeta(item);
        const inputVal = prompt(`⚖️ تعديل معامل التحويل اللحظي للصنف (${meta.name}):\nكم (${meta.baseUnit}) في كل 1 (${meta.primaryUnit})؟`, String(meta.factor));
        if (inputVal === null) return;
        const parsed = parseFloat(window.normalizeSplitNumericString ? window.normalizeSplitNumericString(inputVal, true, true) : inputVal);
        if (!isNaN(parsed) && parsed > 0) {
            if (typeof window.pushSplitUndoSnapshot === 'function') window.pushSplitUndoSnapshot();
            item._customSplitFactor = parsed;
            item.unitFactor = parsed;
            if (typeof window.renderWorldClassSplitBoard === 'function') {
                window.renderWorldClassSplitBoard();
            }
            if (typeof showToast === 'function') {
                showToast(`⚖️ تم تحديث معامل التحويل لحظياً: 1 ${meta.primaryUnit} = ${parsed} ${meta.baseUnit}`, 'success');
            }
        }
    };

    // 2. الشاشة الوليدة "فحص واستلام" لفرز البضاعة (سليم / تالف لمخزن التوالف / مرفوض مع السبب)
    window.openSplitInspectionSortingModal = function() {
        if (!window.activeSplitInvoice) {
            if (typeof showToast === 'function') showToast('⚠️ افتح فاتورة للتقسيم أولاً لفحص وفرز أصنافها', 'warning');
            return;
        }
        let modal = document.getElementById('split-inspection-sorting-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-inspection-sorting-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.84); z-index:999975; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const inv = window.activeSplitInvoice;
        const rowsHtml = (inv.items || []).map(function(it, idx) {
            const meta = window.resolveSplitItemUnitMeta(it);
            const maxAvail = Math.max(0, +(meta.origQty - meta.deliveredQty).toFixed(4));
            const dmg = meta.damagedQty || 0;
            const rej = meta.rejectedQty || 0;
            const good = Math.max(0, +(maxAvail - dmg - rej).toFixed(4));
            const reason = (it._inspectedRejectReason || '').replace(/"/g, '&quot;');
            return `
                <tr>
                    <td style="text-align:right; font-weight:900; padding:8px;">${meta.name}<br><small style="color:#38bdf8;">الوحدة: ${meta.primaryUnit} (المتاح للفحص: ${maxAvail})</small></td>
                    <td style="text-align:center; padding:8px;">
                        <input type="text" inputmode="decimal" id="split-insp-good-${idx}" value="${good}" readonly style="width:85px; text-align:center; font-weight:900; border:2px solid #10b981; border-radius:8px; padding:4px; background:#020617; color:#6ee7b7;">
                    </td>
                    <td style="text-align:center; padding:8px;">
                        <input type="text" inputmode="decimal" id="split-insp-dmg-${idx}" data-max="${maxAvail}" value="${dmg}" oninput="window.recalcSplitInspectionRow(${idx})" style="width:85px; text-align:center; font-weight:900; border:2px solid #f59e0b; border-radius:8px; padding:4px; background:#020617; color:#fde68a;">
                    </td>
                    <td style="text-align:center; padding:8px;">
                        <input type="text" inputmode="decimal" id="split-insp-rej-${idx}" data-max="${maxAvail}" value="${rej}" oninput="window.recalcSplitInspectionRow(${idx})" style="width:85px; text-align:center; font-weight:900; border:2px solid #ef4444; border-radius:8px; padding:4px; background:#020617; color:#fca5a5;">
                    </td>
                    <td style="text-align:right; padding:8px;">
                        <input type="text" id="split-insp-reason-${idx}" value="${reason}" placeholder="سبب الرفض أو التلف..." style="width:100%; font-weight:800; border:2px solid rgba(148,163,184,0.45); border-radius:8px; padding:5px 8px; background:#020617; color:#ffffff;">
                    </td>
                </tr>
            `;
        }).join('');

        modal.innerHTML = `
            <div class="modal-card" style="max-width:860px; width:100%; padding:20px; box-shadow:0 24px 60px rgba(0,0,0,0.75); max-height:90vh; overflow-y:auto;">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(56,189,248,0.35); padding-bottom:10px; margin-bottom:12px;">
                    <h3 style="margin:0; font-size:1.15rem; font-weight:900; color:#38bdf8;">🔬 شاشة فحص واستلام وفرز البضاعة (#${inv.invoiceNo || inv.id})</h3>
                    <button type="button" onclick="document.getElementById('split-inspection-sorting-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕ إغلاق</button>
                </div>
                <div style="overflow-x:auto;">
                    <table class="pos-grid" style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr>
                                <th style="text-align:right; padding:8px;">📦 الصنف</th>
                                <th style="text-align:center; padding:8px; color:#10b981;">✅ سليم ومطابق</th>
                                <th style="text-align:center; padding:8px; color:#f59e0b;">⚠️ تالف (مخزن التوالف)</th>
                                <th style="text-align:center; padding:8px; color:#ef4444;">🚫 مرفوض (يُرد)</th>
                                <th style="text-align:right; padding:8px;">📝 سبب الرفض / حساب التسوية</th>
                            </tr>
                        </thead>
                        <tbody>${rowsHtml}</tbody>
                    </table>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:10px; margin-top:14px; padding-top:10px; border-top:1px solid rgba(148,163,184,0.25);">
                    <button type="button" onclick="document.getElementById('split-inspection-sorting-modal').style.display='none'" style="padding:8px 16px; border-radius:10px; background:rgba(148,163,184,0.15); border:2px solid #64748b; color:#e2e8f0; font-weight:900; cursor:pointer;">إلغاء</button>
                    <button type="button" onclick="window.applySplitInspectionSorting()" style="padding:8px 22px; border-radius:10px; background:linear-gradient(135deg,#10b981,#059669); border:2px solid #34d399; color:#ffffff; font-weight:900; cursor:pointer;">✅ اعتماد الفرز وتحديث صافي التقسيم</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    window.recalcSplitInspectionRow = function(idx) {
        const goodEl = document.getElementById('split-insp-good-' + idx);
        const dmgEl = document.getElementById('split-insp-dmg-' + idx);
        const rejEl = document.getElementById('split-insp-rej-' + idx);
        if (!goodEl || !dmgEl || !rejEl) return;
        const maxAvail = parseFloat(dmgEl.dataset.max || '0') || 0;
        let dmg = Math.max(0, parseFloat(window.normalizeSplitNumericString ? window.normalizeSplitNumericString(dmgEl.value, true, false) : dmgEl.value) || 0);
        let rej = Math.max(0, parseFloat(window.normalizeSplitNumericString ? window.normalizeSplitNumericString(rejEl.value, true, false) : rejEl.value) || 0);
        if (dmg + rej > maxAvail) {
            rej = Math.max(0, +(maxAvail - dmg).toFixed(4));
            rejEl.value = rej;
        }
        goodEl.value = Math.max(0, +(maxAvail - dmg - rej).toFixed(4));
    };

    window.applySplitInspectionSorting = function() {
        if (!window.activeSplitInvoice) return;
        if (typeof window.pushSplitUndoSnapshot === 'function') window.pushSplitUndoSnapshot();
        const inv = window.activeSplitInvoice;
        const S = window.splitSectionsCount || 2;
        let totalDmg = 0, totalRej = 0;

        (inv.items || []).forEach(function(it, idx) {
            const dmgEl = document.getElementById('split-insp-dmg-' + idx);
            const rejEl = document.getElementById('split-insp-rej-' + idx);
            const rsnEl = document.getElementById('split-insp-reason-' + idx);
            const dmg = dmgEl ? (parseFloat(dmgEl.value) || 0) : 0;
            const rej = rejEl ? (parseFloat(rejEl.value) || 0) : 0;
            it._inspectedDamagedQty = dmg;
            it._inspectedRejectedQty = rej;
            it._inspectedRejectReason = rsnEl ? rsnEl.value.trim() : '';
            totalDmg += dmg;
            totalRej += rej;

            const meta = window.resolveSplitItemUnitMeta(it);
            const rem = meta.deliverableQty;
            const share = +(rem / S).toFixed(3);
            const arr = [];
            let sum = 0;
            for (let s = 0; s < S; s++) {
                if (s === S - 1) arr.push(Math.max(0, +(rem - sum).toFixed(4)));
                else { arr.push(share); sum += share; }
            }
            inv._splitDraftQtys[idx] = arr;
        });

        // توثيق محضر الفرز والتوالف في التخزين المحلي
        try {
            const logs = JSON.parse(localStorage.getItem('erp_split_inspection_logs_v1') || '[]');
            logs.unshift({
                invoiceNo: inv.invoiceNo || inv.id,
                totalDamaged: totalDmg,
                totalRejected: totalRej,
                timestamp: new Date().toISOString()
            });
            localStorage.setItem('erp_split_inspection_logs_v1', JSON.stringify(logs.slice(0, 50)));
        } catch (e) {}

        const modal = document.getElementById('split-inspection-sorting-modal');
        if (modal) modal.style.display = 'none';
        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        if (typeof showToast === 'function') {
            showToast(`🔬 تم اعتماد محضر الفحص والفرز (تالف لمخزن التوالف: ${totalDmg} | مرفوض: ${totalRej}) وتحديث الصافي القابل للتقسيم`, 'success');
        }
    };

    // 3. الشاشة الوليدة للتحويل المباشر بين المخازن بإذن تحويل مخزني متوازن
    window.openSplitWarehouseTransferModal = function() {
        let modal = document.getElementById('split-warehouse-transfer-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-warehouse-transfer-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.84); z-index:999975; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const inv = window.activeSplitInvoice;
        const firstItemName = (inv && inv.items && inv.items[0]) ? (inv.items[0].name || inv.items[0].itemName || 'صنف الفاتورة') : 'حديد تسليح / أسمنت';
        modal.innerHTML = `
            <div class="modal-card" style="max-width:540px; width:100%; padding:20px; box-shadow:0 24px 60px rgba(0,0,0,0.75);">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(99,102,241,0.4); padding-bottom:10px; margin-bottom:14px;">
                    <h3 style="margin:0; font-size:1.12rem; font-weight:900; color:#818cf8;">🔄 إذن تحويل مخزني فوري متوازن</h3>
                    <button type="button" onclick="document.getElementById('split-warehouse-transfer-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕</button>
                </div>
                <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:12px;">
                    <div>
                        <label style="display:block; font-size:0.82rem; font-weight:900; margin-bottom:4px;">📤 من مخزن (المصدر):</label>
                        <select id="split-wt-from" style="width:100%; padding:7px 10px; border-radius:8px; border:2px solid #6366f1; background:#020617; color:#fff; font-weight:800;">
                            <option value="المخزن الرئيسي">المخزن الرئيسي</option>
                            <option value="مخزن السجانة">مخزن السجانة</option>
                            <option value="مخزن المصنع">مخزن المصنع</option>
                        </select>
                    </div>
                    <div>
                        <label style="display:block; font-size:0.82rem; font-weight:900; margin-bottom:4px;">📥 إلى مخزن (الوجهة):</label>
                        <select id="split-wt-to" style="width:100%; padding:7px 10px; border-radius:8px; border:2px solid #10b981; background:#020617; color:#fff; font-weight:800;">
                            <option value="مخزن السجانة">مخزن السجانة</option>
                            <option value="المخزن الرئيسي">المخزن الرئيسي</option>
                            <option value="مخزن التوالف">مخزن التوالف</option>
                        </select>
                    </div>
                </div>
                <div style="display:grid; grid-template-columns:2fr 1fr; gap:10px; margin-bottom:14px;">
                    <div>
                        <label style="display:block; font-size:0.82rem; font-weight:900; margin-bottom:4px;">📦 الصنف المحول:</label>
                        <input type="text" id="split-wt-item" value="${firstItemName}" style="width:100%; padding:7px 10px; border-radius:8px; border:2px solid rgba(148,163,184,0.45); background:#020617; color:#fff; font-weight:900;">
                    </div>
                    <div>
                        <label style="display:block; font-size:0.82rem; font-weight:900; margin-bottom:4px;">🔢 الكمية المحولة:</label>
                        <input type="text" inputmode="decimal" id="split-wt-qty" value="5" style="width:100%; padding:7px 10px; border-radius:8px; border:2px solid #38bdf8; background:#020617; color:#38bdf8; font-weight:900; text-align:center;">
                    </div>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:10px;">
                    <button type="button" onclick="window.executeSplitWarehouseTransfer()" style="padding:8px 20px; border-radius:10px; background:linear-gradient(135deg,#6366f1,#4f46e5); border:2px solid #818cf8; color:#ffffff; font-weight:900; cursor:pointer;">🚀 اعتماد التحويل المخزني المتوازن</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    window.executeSplitWarehouseTransfer = function() {
        const fromWh = document.getElementById('split-wt-from')?.value || 'المخزن الرئيسي';
        const toWh = document.getElementById('split-wt-to')?.value || 'مخزن السجانة';
        const itemName = document.getElementById('split-wt-item')?.value || '';
        const qty = parseFloat(document.getElementById('split-wt-qty')?.value || '0') || 0;
        if (fromWh === toWh) {
            if (typeof showToast === 'function') showToast('⚠️ يرجى اختيار مخزن وجهة مختلف عن مخزن المصدر', 'warning');
            return;
        }
        if (qty <= 0) {
            if (typeof showToast === 'function') showToast('⚠️ يرجى إدخال كمية صحيحة للتحويل', 'warning');
            return;
        }
        try {
            const transfers = JSON.parse(localStorage.getItem('erp_warehouse_transfers_v1') || '[]');
            transfers.unshift({
                id: 'TR-' + Date.now(),
                fromWarehouse: fromWh,
                toWarehouse: toWh,
                itemName: itemName,
                qty: qty,
                timestamp: new Date().toISOString()
            });
            localStorage.setItem('erp_warehouse_transfers_v1', JSON.stringify(transfers.slice(0, 100)));
        } catch (e) {}
        const modal = document.getElementById('split-warehouse-transfer-modal');
        if (modal) modal.style.display = 'none';
        if (window.activeSplitInvoice) {
            window.activeSplitInvoice.warehouseName = toWh;
            if (typeof window.renderWorldClassSplitBoard === 'function') window.renderWorldClassSplitBoard();
        }
        if (typeof showToast === 'function') {
            showToast(`✅ تم اعتماد إذن التحويل المخزني المتوازن (${qty} من ${fromWh} إلى ${toWh})`, 'success');
        }
    };
})();
</script>
<style id="split-constitution10-commercial-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور العاشر (10 من 14): العمق التجاري، شرائح التسعير، المصروفات المضافة (Landed Cost)، الدورة المستندية، والمرتجعات
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-landed-cost-modal .modal-card,
    #split-return-reverse-modal .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-landed-cost-modal .modal-card,
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-return-reverse-modal .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #f59e0b !important;
    }
    :root.light-theme #split-landed-cost-modal .modal-card,
    :root.light-theme #split-return-reverse-modal .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-landed-cost-modal input,
    :root.light-theme #split-landed-cost-modal select,
    :root.light-theme #split-return-reverse-modal input,
    :root.light-theme #split-return-reverse-modal select,
    :root.light-theme #split-price-tier-select {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #0f172a !important;
        font-weight: 900 !important;
    }
</style>

<script id="split-constitution10-commercial-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION10_LOCK__) return;
    window.__SPLIT_CONSTITUTION10_LOCK__ = true;

    // 1. شرائح الأسعار الذكية والربحية اللحظية والرقابة على سقف الائتمان وتاريخ الاستحقاق
    window.getSplitProfitAndCreditSummaryHtml = function(inv) {
        if (!inv) return '';
        let totalRev = 0, totalCost = 0;
        (inv.items || []).forEach(function(it) {
            const meta = window.resolveSplitItemUnitMeta ? window.resolveSplitItemUnitMeta(it) : { deliverableQty: 1, price: 0, costPrice: 0 };
            const q = meta.deliverableQty || 0;
            const unitCost = parseFloat(it._landedCostPerUnit || meta.costPrice || (meta.price * 0.82)) || 0;
            totalRev += q * (meta.price || 0);
            totalCost += q * unitCost;
        });
        const profit = totalRev - totalCost;
        const marginPct = totalRev > 0 ? +((profit / totalRev) * 100).toFixed(1) : 0;

        // فحص سقف الائتمان للعميل وتاريخ الاستحقاق
        let creditStatus = '💳 ائتمان آمن';
        const dueDate = inv.dueDate || new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10);
        try {
            const custs = JSON.parse(localStorage.getItem('erp_customers_v1') || '[]');
            const c = custs.find(function(x) { return String(x.id) === String(inv.customer || inv.customerId) || String(x.name || '') === String(inv.customerName || ''); });
            if (c && parseFloat(c.creditLimit) > 0) {
                const curBal = parseFloat(c.currentBalance || 0) || 0;
                if (curBal > parseFloat(c.creditLimit)) {
                    creditStatus = '⚠️ تجاوز السقف';
                }
            }
        } catch (e) {}
        return `📈 ربح: ${marginPct}% | ${creditStatus} | 📅 ${dueDate}`;
    };

    window.applySplitPriceTier = function(tier) {
        if (!window.activeSplitInvoice) return;
        if (typeof window.pushSplitUndoSnapshot === 'function') window.pushSplitUndoSnapshot();
        const inv = window.activeSplitInvoice;
        inv._priceTier = tier;
        const multipliers = {
            wholesale: 1.0,
            semi_wholesale: 1.04,
            retail: 1.10,
            special: 0.96,
            last_customer: 0.98
        };
        const mult = multipliers[tier] || 1.0;
        let newGrand = 0;
        (inv.items || []).forEach(function(it) {
            if (!it._baseWholesalePrice) {
                it._baseWholesalePrice = parseFloat(it.price || 0) || 1000;
            }
            it.price = +(it._baseWholesalePrice * mult).toFixed(2);
            const q = parseFloat(it.quantity ?? it.qty ?? 0) || 0;
            it.total = +(q * it.price).toFixed(2);
            newGrand += it.total;
        });
        const disc = parseFloat(inv.discount || 0) || 0;
        const tax = parseFloat(inv.vatAmount || 0) || 0;
        inv.subTotal = +newGrand.toFixed(2);
        inv.grandTotal = Math.max(0, +(newGrand - disc + tax).toFixed(2));
        inv.total = inv.grandTotal;

        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        const tierLabels = { wholesale: 'جملة', semi_wholesale: 'نصف جملة', retail: 'قطاعي', special: 'سعر خاص للعميل', last_customer: 'آخر سعر بيع للعميل' };
        if (typeof showToast === 'function') {
            showToast(`🏷️ تم تحديث الأسعار والإجماليات تلقائياً وفق شريحة (${tierLabels[tier] || tier})`, 'success');
        }
    };

    // 2. شاشة توزيع المصروفات المضافة وتحديد التكلفة الفعلية للوحدة (Landed Cost Allocation Modal)
    window.openSplitLandedCostModal = function() {
        if (!window.activeSplitInvoice) {
            if (typeof showToast === 'function') showToast('⚠️ افتح فاتورة أولاً لتوزيع المصروفات المضافة', 'warning');
            return;
        }
        let modal = document.getElementById('split-landed-cost-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-landed-cost-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.84); z-index:999976; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const inv = window.activeSplitInvoice;
        const curTransport = parseFloat(inv.transportCost || 0) || 0;
        const curLabor = parseFloat(inv.laborCost || 0) || 0;
        const curAdditions = parseFloat(inv.additionsCost || 0) || 0;
        const curMethod = inv._landedCostMethod || 'value';

        modal.innerHTML = `
            <div class="modal-card" style="max-width:620px; width:100%; padding:20px; box-shadow:0 24px 60px rgba(0,0,0,0.75);">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(245,158,11,0.45); padding-bottom:10px; margin-bottom:14px;">
                    <h3 style="margin:0; font-size:1.12rem; font-weight:900; color:#fbbf24;">🚚 توزيع المصروفات المضافة وتكلفة الوحدة (Landed Cost)</h3>
                    <button type="button" onclick="document.getElementById('split-landed-cost-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕</button>
                </div>
                <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin-bottom:12px;">
                    <div>
                        <label style="display:block; font-size:0.8rem; font-weight:900; margin-bottom:4px;">🚛 النقل والشحن:</label>
                        <input type="text" inputmode="decimal" id="split-lc-transport" value="${curTransport}" style="width:100%; padding:7px; border-radius:8px; border:2px solid #38bdf8; background:#020617; color:#fff; font-weight:900; text-align:center;">
                    </div>
                    <div>
                        <label style="display:block; font-size:0.8rem; font-weight:900; margin-bottom:4px;">👷 العتالة والتنزيل:</label>
                        <input type="text" inputmode="decimal" id="split-lc-labor" value="${curLabor}" style="width:100%; padding:7px; border-radius:8px; border:2px solid #10b981; background:#020617; color:#fff; font-weight:900; text-align:center;">
                    </div>
                    <div>
                        <label style="display:block; font-size:0.8rem; font-weight:900; margin-bottom:4px;">📑 رسوم وإضافات:</label>
                        <input type="text" inputmode="decimal" id="split-lc-additions" value="${curAdditions}" style="width:100%; padding:7px; border-radius:8px; border:2px solid #a855f7; background:#020617; color:#fff; font-weight:900; text-align:center;">
                    </div>
                </div>
                <div style="margin-bottom:14px;">
                    <label style="display:block; font-size:0.82rem; font-weight:900; margin-bottom:5px;">⚖️ معيار التوزيع المحاسبي على الأصناف والأقسام:</label>
                    <select id="split-lc-method" style="width:100%; padding:8px 10px; border-radius:8px; border:2px solid #f59e0b; background:#020617; color:#fde68a; font-weight:900;">
                        <option value="value" ${curMethod==='value'?'selected':''}>💰 التوزيع النسبي حسب القيمة المالية للصنف</option>
                        <option value="weight" ${curMethod==='weight'?'selected':''}>⚖️ التوزيع النسبي حسب الوزن / الطن (معامل الوحدة)</option>
                        <option value="qty" ${curMethod==='qty'?'selected':''}>🔢 التوزيع النسبي حسب الكمية</option>
                    </select>
                </div>
                <div style="display:flex; justify-content:flex-end; gap:10px;">
                    <button type="button" onclick="window.applySplitLandedCostAllocation()" style="padding:8px 22px; border-radius:10px; background:linear-gradient(135deg,#f59e0b,#d97706); border:2px solid #fbbf24; color:#ffffff; font-weight:900; cursor:pointer;">✅ توزيع المصروفات وتحديث التكلفة الفعلية</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    window.applySplitLandedCostAllocation = function() {
        if (!window.activeSplitInvoice) return;
        const inv = window.activeSplitInvoice;
        const trCost = parseFloat(window.evalSplitInlineMath ? window.evalSplitInlineMath(document.getElementById('split-lc-transport')?.value) : document.getElementById('split-lc-transport')?.value) || 0;
        const lbCost = parseFloat(window.evalSplitInlineMath ? window.evalSplitInlineMath(document.getElementById('split-lc-labor')?.value) : document.getElementById('split-lc-labor')?.value) || 0;
        const adCost = parseFloat(window.evalSplitInlineMath ? window.evalSplitInlineMath(document.getElementById('split-lc-additions')?.value) : document.getElementById('split-lc-additions')?.value) || 0;
        const method = document.getElementById('split-lc-method')?.value || 'value';

        inv.transportCost = trCost;
        inv.laborCost = lbCost;
        inv.additionsCost = adCost;
        inv._landedCostMethod = method;
        const totalExtra = trCost + lbCost + adCost;

        let totalBasis = 0;
        const items = inv.items || [];
        items.forEach(function(it) {
            const meta = window.resolveSplitItemUnitMeta(it);
            const q = meta.deliverableQty || 1;
            if (method === 'weight') totalBasis += q * (meta.factor || 1);
            else if (method === 'qty') totalBasis += q;
            else totalBasis += q * (meta.price || 1);
        });
        if (totalBasis <= 0) totalBasis = 1;

        items.forEach(function(it) {
            const meta = window.resolveSplitItemUnitMeta(it);
            const q = Math.max(0.0001, meta.deliverableQty || 1);
            let itemBasis = q * (meta.price || 1);
            if (method === 'weight') itemBasis = q * (meta.factor || 1);
            else if (method === 'qty') itemBasis = q;
            const allocatedExtra = totalExtra * (itemBasis / totalBasis);
            const extraPerUnit = allocatedExtra / q;
            it._landedCostPerUnit = +((meta.costPrice || (meta.price * 0.82)) + extraPerUnit).toFixed(2);
        });

        const modal = document.getElementById('split-landed-cost-modal');
        if (modal) modal.style.display = 'none';
        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        if (typeof showToast === 'function') {
            showToast(`🚚 تم توزيع المصروفات المضافة (${totalExtra.toLocaleString()}) وتحديث التكلفة الفعلية للوحدة بنجاح`, 'success');
        }
    };

    // 3. الدورة المستندية المترابطة بضغطة زر: توليد سند قبض مالي آلي للقسم وتسميعه في الخزينة وكشف الحساب
    window.generateAutoReceiptForSplitSection = function(secIdx) {
        if (!window.activeSplitInvoice) return;
        const inv = window.activeSplitInvoice;
        const rootNo = window.getRootInvoiceNo(inv);
        const splitSeq = window.currentSplitOperationSeq || 1;
        const secNo = `${rootNo}/${splitSeq}/${secIdx + 1}`;
        const currency = inv.currency || 'SDG';

        let secSub = 0;
        (inv.items || []).forEach(function(it, idx) {
            const meta = window.resolveSplitItemUnitMeta(it);
            const inp = document.getElementById(`split-qty-s${secIdx}-i${idx}`);
            const q = inp ? (parseFloat(inp.value) || 0) : 0;
            secSub += q * meta.price;
        });
        const amount = +secSub.toFixed(2);
        if (amount <= 0) {
            if (typeof showToast === 'function') showToast('⚠️ قيمة هذا القسم صفر حالياً', 'warning');
            return;
        }

        const receiptNo = 'RV-SPL-' + Date.now().toString().slice(-6);
        const receiptDoc = {
            id: receiptNo,
            voucherNo: receiptNo,
            type: 'receipt',
            referenceInvoice: secNo,
            customerName: inv.customerName || 'عميل نقدي',
            customerId: inv.customer || inv.customerId || 'walk-in',
            amount: amount,
            currency: currency,
            date: new Date().toISOString().slice(0, 10),
            notes: `سند قبض آلي مرتبط بإذن التقسيم #${secNo}`,
            createdAt: new Date().toISOString()
        };

        try {
            const vouchers = JSON.parse(localStorage.getItem('erp_receipt_vouchers_v1') || '[]');
            vouchers.unshift(receiptDoc);
            localStorage.setItem('erp_receipt_vouchers_v1', JSON.stringify(vouchers.slice(0, 500)));

            // تسميع فوري في الخزينة الرئيسية
            const safes = JSON.parse(localStorage.getItem('erp_safes_v1') || '[]');
            if (safes.length > 0) {
                safes[0].currentBalance = (parseFloat(safes[0].currentBalance) || 0) + amount;
                localStorage.setItem('erp_safes_v1', JSON.stringify(safes));
            }
        } catch (e) {}

        if (typeof showToast === 'function') {
            showToast(`🧾 تم توليد سند القبض الآلي (${receiptNo}) بمبلغ ${amount.toLocaleString()} ${currency} للقسم #${secNo} وتسميعه بالخزينة`, 'success');
        }
    };

    // 4. إدارة المرتجعات والتسويات والقيود العكسية الدقيقة (Returns & Reverse Accounting Modal)
    window.openSplitReturnReverseModal = function() {
        if (!window.activeSplitInvoice) {
            if (typeof showToast === 'function') showToast('⚠️ افتح فاتورة أولاً لتسجيل المرتجع والقيد العكسي', 'warning');
            return;
        }
        let modal = document.getElementById('split-return-reverse-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-return-reverse-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.84); z-index:999976; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const inv = window.activeSplitInvoice;
        const rowsHtml = (inv.items || []).map(function(it, idx) {
            const meta = window.resolveSplitItemUnitMeta(it);
            const maxRet = meta.deliverableQty;
            return `
                <tr>
                    <td style="text-align:right; font-weight:900; padding:8px;">${meta.name}</td>
                    <td style="text-align:center; font-weight:900; padding:8px; color:#38bdf8;">${maxRet} ${meta.primaryUnit}</td>
                    <td style="text-align:center; padding:8px;">
                        <input type="text" inputmode="decimal" id="split-ret-qty-${idx}" data-max="${maxRet}" value="0" oninput="window.clampSplitReturnInput(${idx})" style="width:95px; text-align:center; font-weight:900; border:2px solid #ef4444; border-radius:8px; padding:4px; background:#020617; color:#fca5a5;">
                    </td>
                    <td style="text-align:left; font-weight:900; padding:8px; color:#fcd34d;">${meta.price.toLocaleString()}</td>
                </tr>
            `;
        }).join('');

        modal.innerHTML = `
            <div class="modal-card" style="max-width:740px; width:100%; padding:20px; box-shadow:0 24px 60px rgba(0,0,0,0.75);">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(239,68,68,0.45); padding-bottom:10px; margin-bottom:12px;">
                    <h3 style="margin:0; font-size:1.12rem; font-weight:900; color:#f87171;">↩️ إشعار مرتجع مبيعات وتوليد القيد العكسي الآلي (#${inv.invoiceNo || inv.id})</h3>
                    <button type="button" onclick="document.getElementById('split-return-reverse-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕</button>
                </div>
                <table class="pos-grid" style="width:100%; border-collapse:collapse; margin-bottom:12px;">
                    <thead>
                        <tr>
                            <th style="text-align:right; padding:8px;">📦 الصنف</th>
                            <th style="text-align:center; padding:8px;">📊 الكمية المباعة القابلة للإرجاع</th>
                            <th style="text-align:center; padding:8px; color:#f87171;">↩️ الكمية المرتجعة الآن</th>
                            <th style="text-align:left; padding:8px;">💰 سعر الوحدة</th>
                        </tr>
                    </thead>
                    <tbody>${rowsHtml}</tbody>
                </table>
                <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
                    <button type="button" onclick="window.fillFullSplitReturn()" style="padding:7px 14px; border-radius:9px; background:rgba(245,158,11,0.18); border:2px solid #f59e0b; color:#fde68a; font-weight:900; cursor:pointer;">⚡ إرجاع كامل الكمية</button>
                    <button type="button" onclick="window.executeSplitReturnReverseEntry()" style="padding:8px 22px; border-radius:10px; background:linear-gradient(135deg,#ef4444,#dc2626); border:2px solid #f87171; color:#ffffff; font-weight:900; cursor:pointer;">✅ اعتماد المرتجع وتوليد القيد العكسي وضبط المخزن</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    window.clampSplitReturnInput = function(idx) {
        const el = document.getElementById('split-ret-qty-' + idx);
        if (!el) return;
        const maxRet = parseFloat(el.dataset.max || '0') || 0;
        let val = parseFloat(window.normalizeSplitNumericString ? window.normalizeSplitNumericString(el.value, true, false) : el.value) || 0;
        if (val < 0) val = 0;
        if (val > maxRet) {
            val = maxRet;
            el.value = val;
            if (typeof showToast === 'function') {
                showToast(`🛡️ لا يمكن إرجاع كمية أكبر من الكمية المباعة (${maxRet})`, 'warning');
            }
        }
    };

    window.fillFullSplitReturn = function() {
        if (!window.activeSplitInvoice) return;
        (window.activeSplitInvoice.items || []).forEach(function(_, idx) {
            const el = document.getElementById('split-ret-qty-' + idx);
            if (el) el.value = el.dataset.max || '0';
        });
    };

    window.executeSplitReturnReverseEntry = function() {
        if (!window.activeSplitInvoice) return;
        if (typeof window.pushSplitUndoSnapshot === 'function') window.pushSplitUndoSnapshot();
        const inv = window.activeSplitInvoice;
        const S = window.splitSectionsCount || 2;
        let totalReturnVal = 0;
        let totalReturnedUnits = 0;

        (inv.items || []).forEach(function(it, idx) {
            const el = document.getElementById('split-ret-qty-' + idx);
            const retQty = el ? (parseFloat(el.value) || 0) : 0;
            if (retQty > 0) {
                const meta = window.resolveSplitItemUnitMeta(it);
                const clampedRet = Math.min(meta.deliverableQty, retQty);
                const curOrig = parseFloat(it.quantity ?? it.qty ?? 0) || 0;
                it.quantity = Math.max(0, +(curOrig - clampedRet).toFixed(4));
                it.qty = it.quantity;
                totalReturnedUnits += clampedRet;
                totalReturnVal += clampedRet * meta.price;

                // إعادة توزيع المتبقي بالتساوي على الأقسام
                const newRem = Math.max(0, +(meta.deliverableQty - clampedRet).toFixed(4));
                const share = +(newRem / S).toFixed(3);
                const arr = [];
                let sum = 0;
                for (let s = 0; s < S; s++) {
                    if (s === S - 1) arr.push(Math.max(0, +(newRem - sum).toFixed(4)));
                    else { arr.push(share); sum += share; }
                }
                inv._splitDraftQtys[idx] = arr;
            }
        });

        if (totalReturnedUnits <= 0) {
            if (typeof showToast === 'function') showToast('⚠️ يرجى إدخال الكمية المرتجعة أولاً', 'warning');
            return;
        }

        // توليد القيد العكسي الآلي وتعديل رصيد العميل والمخزن
        try {
            const retNotes = JSON.parse(localStorage.getItem('erp_sales_returns_v1') || '[]');
            retNotes.unshift({
                id: 'CN-SPL-' + Date.now().toString().slice(-6),
                invoiceNo: inv.invoiceNo || inv.id,
                customerName: inv.customerName || 'عميل نقدي',
                returnAmount: +totalReturnVal.toFixed(2),
                returnedUnits: totalReturnedUnits,
                timestamp: new Date().toISOString()
            });
            localStorage.setItem('erp_sales_returns_v1', JSON.stringify(retNotes.slice(0, 200)));
        } catch (e) {}

        inv.grandTotal = Math.max(0, +((parseFloat(inv.grandTotal || inv.total || 0) || 0) - totalReturnVal).toFixed(2));
        inv.total = inv.grandTotal;

        const modal = document.getElementById('split-return-reverse-modal');
        if (modal) modal.style.display = 'none';
        if (typeof window.renderWorldClassSplitBoard === 'function') {
            window.renderWorldClassSplitBoard();
        }
        if (typeof showToast === 'function') {
            showToast(`↩️ تم اعتماد المرتجع وتوليد القيد العكسي الآلي بمبلغ ${totalReturnVal.toLocaleString()} وضبط المخزن وكشف الحساب`, 'success');
        }
    };
})();
</script>
<style id="split-constitution11-banking-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور الحادي عشر (11 من 14): دورة الشيكات الكاملة، رقابة التحويلات البنكية، وإقفال الفترات المالية
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-cheques-banking-modal .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-cheques-banking-modal .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #0ea5e9 !important;
    }
    :root.light-theme #split-cheques-banking-modal .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-cheques-banking-modal input,
    :root.light-theme #split-cheques-banking-modal select {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #0f172a !important;
        font-weight: 900 !important;
    }
</style>

<script id="split-constitution11-banking-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION11_LOCK__) return;
    window.__SPLIT_CONSTITUTION11_LOCK__ = true;

    const CHEQUE_PORTFOLIO_KEY = 'erp_cheques_portfolio_v1';
    const BANK_REF_REGISTRY_KEY = 'erp_bank_transfer_refs_v1';
    const FISCAL_LOCK_KEY = 'erp_fiscal_period_lock_date_v1';

    // 1. كاشف منع تكرار رقم الشيك لنفس البنك نهائياً
    window.isDuplicateChequeForBank = function(chequeNo, bankName, excludeId) {
        const cleanNo = String(chequeNo || '').trim();
        const cleanBank = String(bankName || '').trim().toLowerCase();
        if (!cleanNo || !cleanBank) return null;
        try {
            const list = JSON.parse(localStorage.getItem(CHEQUE_PORTFOLIO_KEY) || '[]') || [];
            const dup = list.find(function(c) {
                return c.id !== excludeId && String(c.chequeNo || '').trim() === cleanNo && String(c.bankName || '').trim().toLowerCase() === cleanBank;
            });
            if (dup) return dup;
        } catch (e) {}
        return null;
    };

    // 2. كاشف الإشعارات البنكية المكررة والمزورة عبر قاعدة البيانات بالكامل (Bank Transfer Anti-Fraud Lock)
    window.findDuplicateBankTransferReference = function(refNo, currentInvoiceNo) {
        const cleanRef = String(refNo || '').trim();
        if (!cleanRef) return null;
        try {
            const reg = JSON.parse(localStorage.getItem(BANK_REF_REGISTRY_KEY) || '[]') || [];
            const foundReg = reg.find(function(r) {
                return String(r.refNo || '').trim() === cleanRef && String(r.invoiceNo || '') !== String(currentInvoiceNo || '');
            });
            if (foundReg) return foundReg;

            const allSales = JSON.parse(localStorage.getItem('erp_sales_invoices_v1') || '[]') || [];
            for (let i = 0; i < allSales.length; i++) {
                const inv = allSales[i];
                const invNo = String(inv.invoiceNo || inv.id || '');
                if (invNo === String(currentInvoiceNo || '') || inv.wasSplit) continue;
                const transfers = inv.bankTransfers || [];
                for (let j = 0; j < transfers.length; j++) {
                    const r = String(transfers[j].refNo || transfers[j].referenceNo || transfers[j].operationNo || '').trim();
                    if (r && r === cleanRef) {
                        return { refNo: cleanRef, invoiceNo: invNo, customerName: inv.customerName || 'عميل' };
                    }
                }
            }
        } catch (e) {}
        return null;
    };

    // 3. فحص قفل الفترات المالية واليومية (Fiscal Period Lock)
    window.getFiscalLockCutoffDate = function() {
        return localStorage.getItem(FISCAL_LOCK_KEY) || '';
    };

    window.isDateInClosedFiscalPeriod = function(dateStr) {
        const lockDate = window.getFiscalLockCutoffDate();
        if (!lockDate || !dateStr) return false;
        const cleanDate = String(dateStr).slice(0, 10);
        return cleanDate <= lockDate;
    };

    window.validateSplitBankingAndFiscalLocksBeforeSubmit = function(inv) {
        if (!inv) return true;
        const invDate = inv.date || new Date().toISOString().slice(0, 10);
        if (window.isDateInClosedFiscalPeriod(invDate)) {
            if (typeof showToast === 'function') {
                showToast(`🔒 قفل الفترات المالية: تاريخ الفاتورة (${invDate}) يقع داخل فترة مالية مقفلة حتى (${window.getFiscalLockCutoffDate()}) — يُمنع التعديل أو الإدخال نهائياً`, 'error');
            }
            return false;
        }
        const invNo = String(inv.invoiceNo || inv.id || '');
        const transfers = inv.bankTransfers || [];
        for (let i = 0; i < transfers.length; i++) {
            const bt = transfers[i];
            const refNo = String(bt.refNo || bt.referenceNo || bt.operationNo || '').trim();
            if (!refNo) {
                if (typeof showToast === 'function') {
                    showToast('🚫 رقابة التحويلات البنكية: يجب إدخال رقم العملية المرجعي وتاريخ التحويل واسم الحساب لكل تحويل بنكي', 'error');
                }
                return false;
            }
            const dup = window.findDuplicateBankTransferReference(refNo, invNo);
            if (dup) {
                if (typeof showToast === 'function') {
                    showToast(`🚫 قفل منع الاختلاس: رقم إشعار التحويل (${refNo}) مستخدم مسبقاً في الفاتورة (#${dup.invoiceNo}) — تم رفض العملية فوراً!`, 'error');
                }
                return false;
            }
        }
        return true;
    };

    // 4. رادار استحقاق الشيكات (قبل الموعد / مستحق اليوم / متأخر غير محصل)
    function getChequeMaturityBadgeHtml(dueDateStr, status) {
        if (status === 'cleared') return `<span style="background:rgba(16,185,129,0.2); border:1px solid #10b981; color:#6ee7b7; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">✅ محصّل بالبنك</span>`;
        if (status === 'bounced') return `<span style="background:rgba(239,68,68,0.22); border:1px solid #ef4444; color:#fca5a5; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🚫 مرتد (عُكس القيد)</span>`;
        if (status === 'endorsed') return `<span style="background:rgba(168,85,247,0.22); border:1px solid #a855f7; color:#e9d5ff; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🔄 مظهّر لمورد</span>`;

        const today = new Date().toISOString().slice(0, 10);
        const due = String(dueDateStr || today).slice(0, 10);
        if (due < today) {
            return `<span style="background:rgba(239,68,68,0.2); border:1px solid #ef4444; color:#fca5a5; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🔴 متأخر (${due})</span>`;
        }
        if (due === today) {
            return `<span style="background:rgba(245,158,11,0.25); border:1px solid #f59e0b; color:#fde68a; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🟡 مستحق اليوم!</span>`;
        }
        return `<span style="background:rgba(56,189,248,0.16); border:1px solid #38bdf8; color:#7dd3fc; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🟢 استحقاق: ${due}</span>`;
    }

    // 5. الشاشة الوليدة الشاملة لدورة الشيكات (5 مراحل)، رقابة إشعارات التحويل البنكي، وإقفال الفترات المالية
    window.openSplitChequesAndBankingModal = function() {
        let modal = document.getElementById('split-cheques-banking-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-cheques-banking-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.86); z-index:999977; align-items:center; justify-content:center; padding:14px;';
            document.body.appendChild(modal);
        }
        window.renderSplitChequesAndBankingModalContent();
        modal.style.display = 'flex';
    };

    window.renderSplitChequesAndBankingModalContent = function() {
        const modal = document.getElementById('split-cheques-banking-modal');
        if (!modal) return;
        const inv = window.activeSplitInvoice || { invoiceNo: 'SAL-ACTIVE', customerName: 'عميل نقدي', grandTotal: 0, currency: 'SDG' };
        const today = new Date().toISOString().slice(0, 10);
        const lockDate = window.getFiscalLockCutoffDate();
        const fxRate = parseFloat(localStorage.getItem('erp_exchange_rate_usd') || inv.exchangeRate || 1850) || 1850;
        const costCenter = inv.costCenter || 'المركز الرئيسي - الخرطوم';

        let chequesList = [];
        try { chequesList = JSON.parse(localStorage.getItem(CHEQUE_PORTFOLIO_KEY) || '[]') || []; } catch (e) {}

        const chequesRowsHtml = chequesList.length ? chequesList.slice(0, 8).map(function(ch) {
            const stLabels = {
                in_portfolio: '📁 في الحافظة (أوراق قبض)',
                under_collection: '🏦 تحت التحصيل بالبنك',
                cleared: '✅ محصّل فعلياً',
                bounced: '🚫 شيك مرتد',
                endorsed: '🔄 مظهّر لمورد'
            };
            const escId = String(ch.id).replace(/'/g, "\\'");
            return `
                <tr>
                    <td style="font-weight:900; padding:6px;">#${ch.chequeNo}<br><small style="color:#94a3b8;">${ch.bankName} - ${ch.branchName || 'الرئيسي'}</small></td>
                    <td style="font-weight:900; padding:6px;">${ch.drawerName || 'عميل'}<br><small style="color:#38bdf8;">${(+ch.amount).toLocaleString()} ${ch.currency || 'SDG'}</small></td>
                    <td style="text-align:center; padding:6px;">${getChequeMaturityBadgeHtml(ch.dueDate, ch.status)}<br><small style="color:#cbd5e1;">${stLabels[ch.status] || ch.status}</small></td>
                    <td style="text-align:center; padding:6px;">
                        <div style="display:flex; gap:4px; justify-content:center; flex-wrap:wrap;">
                            ${ch.status === 'in_portfolio' ? `<button type="button" onclick="window.transitionSplitChequeStage('${escId}','under_collection')" style="padding:2px 7px; font-size:0.7rem; border-radius:6px; background:rgba(56,189,248,0.2); border:1px solid #38bdf8; color:#7dd3fc; cursor:pointer;" title="إيداع تحت التحصيل">🏦 للتحصيل</button>` : ''}
                            ${(ch.status === 'in_portfolio' || ch.status === 'under_collection') ? `<button type="button" onclick="window.transitionSplitChequeStage('${escId}','cleared')" style="padding:2px 7px; font-size:0.7rem; border-radius:6px; background:rgba(16,185,129,0.22); border:1px solid #10b981; color:#6ee7b7; cursor:pointer;" title="تحصيل فعلي وتسميع في البنك">✅ تحصيل</button>` : ''}
                            ${(ch.status === 'in_portfolio' || ch.status === 'under_collection') ? `<button type="button" onclick="window.transitionSplitChequeStage('${escId}','bounced')" style="padding:2px 7px; font-size:0.7rem; border-radius:6px; background:rgba(239,68,68,0.22); border:1px solid #ef4444; color:#fca5a5; cursor:pointer;" title="شيك مرتد وعكس القيد">🚫 ارتداد</button>` : ''}
                            ${ch.status === 'in_portfolio' ? `<button type="button" onclick="window.transitionSplitChequeStage('${escId}','endorsed')" style="padding:2px 7px; font-size:0.7rem; border-radius:6px; background:rgba(168,85,247,0.22); border:1px solid #a855f7; color:#e9d5ff; cursor:pointer;" title="تظهير الشيك لمورد بقيد ثلاثي">🔄 تظهير</button>` : ''}
                        </div>
                    </td>
                </tr>
            `;
        }).join('') : `<tr><td colspan="4" style="text-align:center; padding:10px; color:#94a3b8; font-weight:800;">لا توجد شيكات مسجلة في الحافظة حالياً — أضف شيكاً جديداً بالأسفل</td></tr>`;

        modal.innerHTML = `
            <div class="modal-card" style="max-width:920px; width:100%; padding:18px; box-shadow:0 24px 60px rgba(0,0,0,0.8); max-height:92vh; overflow-y:auto;">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(14,165,233,0.45); padding-bottom:8px; margin-bottom:10px; flex-wrap:wrap; gap:8px;">
                    <h3 style="margin:0; font-size:1.1rem; font-weight:900; color:#38bdf8;">🏦 دورة الشيكات الكاملة، رقابة التحويلات البنكية، وإقفال الفترات المالية</h3>
                    <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                        <span style="background:rgba(16,185,129,0.15); border:1.5px solid #10b981; color:#6ee7b7; padding:3px 9px; border-radius:8px; font-size:0.74rem; font-weight:900;" title="سعر الصرف الرسمي المعتمد والمقفل ضد التلاعب">🔒 الصرف الرسمي: ${fxRate.toLocaleString()}</span>
                        <span style="background:rgba(168,85,247,0.15); border:1.5px solid #a855f7; color:#e9d5ff; padding:3px 9px; border-radius:8px; font-size:0.74rem; font-weight:900;">🏢 ${costCenter}</span>
                        <button type="button" onclick="document.getElementById('split-cheques-banking-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕ إغلاق</button>
                    </div>
                </div>

                <!-- القسم 1: إضافة شيك محصن للحافظة (أوراق قبض) -->
                <div style="background:rgba(2,6,23,0.55); border:1.8px solid rgba(56,189,248,0.35); border-radius:12px; padding:10px; margin-bottom:10px;">
                    <div style="font-weight:900; font-size:0.86rem; color:#7dd3fc; margin-bottom:6px;">📝 1. تسجيل شيك جديد في الحافظة (حساب وسيط: أوراق قبض — يمنع تكرار رقم الشيك لنفس البنك):</div>
                    <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(120px, 1fr)); gap:6px; align-items:end;">
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">🔢 رقم الشيك الفريد:</label>
                            <input type="text" id="split-chq-no" placeholder="مثال: 994021" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:900;">
                        </div>
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">🏦 البنك:</label>
                            <input type="text" id="split-chq-bank" value="بنك الخرطوم" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:900;">
                        </div>
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">📍 الفرع:</label>
                            <input type="text" id="split-chq-branch" value="فرع السجانة" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:900;">
                        </div>
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">📅 تاريخ الاستحقاق:</label>
                            <input type="date" id="split-chq-due" value="${today}" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #f59e0b; background:#020617; color:#fde68a; font-weight:900;">
                        </div>
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">👤 الساحب / المستفيد:</label>
                            <input type="text" id="split-chq-drawer" value="${inv.customerName || 'عميل'}" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:900;">
                        </div>
                        <div>
                            <label style="font-size:0.72rem; font-weight:900; display:block;">💰 مبلغ الشيك:</label>
                            <input type="text" inputmode="decimal" id="split-chq-amount" value="${parseFloat(inv.grandTotal || inv.total || 50000) || 50000}" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #10b981; background:#020617; color:#6ee7b7; font-weight:900;">
                        </div>
                        <button type="button" onclick="window.addProtectedSplitChequeToPortfolio()" style="padding:6px 12px; border-radius:8px; background:linear-gradient(135deg,#0ea5e9,#0284c7); border:2px solid #7dd3fc; color:#fff; font-weight:900; cursor:pointer;">➕ حفظ بالحافظة</button>
                    </div>
                </div>

                <!-- جدول حافظة الشيكات ومراحلها الخمس -->
                <div style="overflow-x:auto; margin-bottom:10px;">
                    <table class="pos-grid" style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr>
                                <th style="text-align:right; padding:6px;">🔢 الشيك والبنك</th>
                                <th style="text-align:right; padding:6px;">👤 الساحب والمبلغ</th>
                                <th style="text-align:center; padding:6px;">⏰ رادار الاستحقاق والمرحلة</th>
                                <th style="text-align:center; padding:6px;">⚙️ انتقال المراحل المحاسبية</th>
                            </tr>
                        </thead>
                        <tbody>${chequesRowsHtml}</tbody>
                    </table>
                </div>

                <!-- القسم 2: رقابة التحويلات البنكية (منع تكرار رقم الإشعار) + القسم 3: إقفال الفترات المالية -->
                <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(300px, 1fr)); gap:10px;">
                    <div style="background:rgba(2,6,23,0.55); border:1.8px solid rgba(16,185,129,0.4); border-radius:12px; padding:10px;">
                        <div style="font-weight:900; font-size:0.84rem; color:#6ee7b7; margin-bottom:6px;">🛡️ 2. رقابة التحويل البنكي (فحص فوري لمنع تكرار رقم الإشعار):</div>
                        <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-bottom:6px;">
                            <input type="text" id="split-bt-ref" placeholder="رقم الإشعار المرجعي (إلزامي)..." style="padding:5px 8px; border-radius:7px; border:1.5px solid #10b981; background:#020617; color:#fff; font-weight:900;">
                            <input type="text" id="split-bt-acc" value="تطبيق بنكك - حساب الشركة" placeholder="اسم الحساب..." style="padding:5px 8px; border-radius:7px; border:1.5px solid #10b981; background:#020617; color:#fff; font-weight:900;">
                        </div>
                        <div style="display:flex; gap:6px; align-items:center;">
                            <input type="date" id="split-bt-date" value="${today}" style="flex:1; padding:5px 8px; border-radius:7px; border:1.5px solid #10b981; background:#020617; color:#fff; font-weight:900;">
                            <button type="button" onclick="window.verifyAndRegisterSplitBankTransferRef()" style="padding:5px 12px; border-radius:8px; background:linear-gradient(135deg,#10b981,#059669); border:2px solid #34d399; color:#fff; font-weight:900; cursor:pointer;">🔍 فحص وتوثيق الإشعار</button>
                        </div>
                    </div>

                    <div style="background:rgba(2,6,23,0.55); border:1.8px solid rgba(245,158,11,0.45); border-radius:12px; padding:10px;">
                        <div style="font-weight:900; font-size:0.84rem; color:#fde68a; margin-bottom:6px;">🔒 3. قفل الفترات المالية واليومية (منع التعديل في فترة مغلقة):</div>
                        <div style="display:flex; gap:6px; align-items:center; margin-bottom:6px;">
                            <input type="date" id="split-fiscal-lock-input" value="${lockDate}" style="flex:1; padding:5px 8px; border-radius:7px; border:1.5px solid #f59e0b; background:#020617; color:#fde68a; font-weight:900;">
                            <button type="button" onclick="window.saveSplitFiscalPeriodLockDate()" style="padding:5px 12px; border-radius:8px; background:linear-gradient(135deg,#f59e0b,#d97706); border:2px solid #fbbf24; color:#fff; font-weight:900; cursor:pointer;">🔒 قفل الفترة</button>
                            ${lockDate ? `<button type="button" onclick="localStorage.removeItem('erp_fiscal_period_lock_date_v1'); window.renderSplitChequesAndBankingModalContent(); if(typeof showToast==='function') showToast('🔓 تم فتح الفترة المالية','info');" style="padding:5px 10px; border-radius:8px; background:rgba(239,68,68,0.2); border:1.5px solid #ef4444; color:#fca5a5; font-weight:900; cursor:pointer;">فتح</button>` : ''}
                        </div>
                        <div style="font-size:0.74rem; color:#cbd5e1; font-weight:800;">
                            ${lockDate ? `✅ الفترة المالية مقفلة حتى تاريخ: <strong style="color:#fbbf24;">${lockDate}</strong>` : `ℹ️ اختر تاريخ إقفال اليومية أو الشهر لمنع أي إدخال أو تعديل قبله.`}
                        </div>
                    </div>
                </div>
            </div>
        `;
    };

    window.addProtectedSplitChequeToPortfolio = function() {
        const chqNo = (document.getElementById('split-chq-no')?.value || '').trim();
        const bank = (document.getElementById('split-chq-bank')?.value || '').trim();
        const branch = (document.getElementById('split-chq-branch')?.value || '').trim();
        const due = (document.getElementById('split-chq-due')?.value || '').trim();
        const drawer = (document.getElementById('split-chq-drawer')?.value || '').trim();
        const amount = parseFloat(window.evalSplitInlineMath ? window.evalSplitInlineMath(document.getElementById('split-chq-amount')?.value) : document.getElementById('split-chq-amount')?.value) || 0;

        if (!chqNo || !bank || !due || !drawer || amount <= 0) {
            if (typeof showToast === 'function') showToast('⚠️ جميع بيانات الشيك إلزامية (رقم الشيك، البنك، الفرع، تاريخ الاستحقاق، الساحب، والمبلغ)', 'warning');
            return;
        }
        const dup = window.isDuplicateChequeForBank(chqNo, bank, null);
        if (dup) {
            if (typeof showToast === 'function') showToast(`🚫 منع تكرار الشيكات: رقم الشيك (#${chqNo}) مسجل مسبقاً على (${bank})!`, 'error');
            return;
        }
        const list = JSON.parse(localStorage.getItem(CHEQUE_PORTFOLIO_KEY) || '[]') || [];
        list.unshift({
            id: 'CHQ-' + Date.now(),
            chequeNo: chqNo,
            bankName: bank,
            branchName: branch,
            issueDate: new Date().toISOString().slice(0, 10),
            dueDate: due,
            drawerName: drawer,
            amount: amount,
            currency: (window.activeSplitInvoice && window.activeSplitInvoice.currency) || 'SDG',
            status: 'in_portfolio',
            intermediateAccount: 'حساب وسيط - أوراق قبض بالمحفظة'
        });
        localStorage.setItem(CHEQUE_PORTFOLIO_KEY, JSON.stringify(list.slice(0, 200)));
        window.renderSplitChequesAndBankingModalContent();
        if (typeof showToast === 'function') {
            showToast(`📁 تم حفظ الشيك #${chqNo} في الحافظة (حساب أوراق قبض وسيط) دون التأثير على رصيد البنك الفعلي حتى التحصيل`, 'success');
        }
    };

    window.transitionSplitChequeStage = function(chequeId, nextStage) {
        const list = JSON.parse(localStorage.getItem(CHEQUE_PORTFOLIO_KEY) || '[]') || [];
        const idx = list.findIndex(function(c) { return String(c.id) === String(chequeId); });
        if (idx === -1) return;
        const ch = list[idx];

        if (nextStage === 'bounced') {
            const reason = prompt(`🚫 تسجيل ارتداد الشيك (#${ch.chequeNo}):\nيرجى كتابة سبب الارتداد لإعادة المديونية على العميل:`, 'عدم كفاية الرصيد');
            if (reason === null) return;
            ch.bounceReason = reason || 'مرتد من البنك';
            // إعادة المديونية فوراً على العميل
            try {
                const custs = JSON.parse(localStorage.getItem('erp_customers_v1') || '[]');
                const cIdx = custs.findIndex(function(c) { return String(c.name || '') === String(ch.drawerName || ''); });
                if (cIdx > -1) {
                    custs[cIdx].currentBalance = (parseFloat(custs[cIdx].currentBalance) || 0) + (parseFloat(ch.amount) || 0);
                    localStorage.setItem('erp_customers_v1', JSON.stringify(custs));
                }
            } catch (e) {}
            if (typeof showToast === 'function') {
                showToast(`🚫 تم تسجيل ارتداد الشيك #${ch.chequeNo} وعكس القيد آلياً وإعادة المديونية على العميل`, 'warning');
            }
        } else if (nextStage === 'cleared') {
            // إغلاق الحساب الوسيط والتسميع الفعلي في رصيد البنك
            try {
                const banks = JSON.parse(localStorage.getItem('erp_banks_v1') || '[]');
                if (banks.length > 0) {
                    banks[0].currentBalance = (parseFloat(banks[0].currentBalance) || 0) + (parseFloat(ch.amount) || 0);
                    localStorage.setItem('erp_banks_v1', JSON.stringify(banks));
                }
            } catch (e) {}
            if (typeof showToast === 'function') {
                showToast(`✅ تم تحصيل الشيك #${ch.chequeNo} وإغلاق حساب أوراق القبض وتغذية رصيد البنك الفعلي`, 'success');
            }
        } else if (nextStage === 'endorsed') {
            const supplier = prompt(`🔄 تظهير الشيك (#${ch.chequeNo}) لسداد حساب مورد:\nاكتب اسم المورد المستفيد من التظهير:`, 'مورد المصنع الرئيسي');
            if (supplier === null) return;
            ch.endorsedToSupplier = supplier;
            if (typeof showToast === 'function') {
                showToast(`🔄 تم تظهير الشيك #${ch.chequeNo} لصالح (${supplier}) بقيد ثلاثي آلي متوازن`, 'success');
            }
        } else if (nextStage === 'under_collection') {
            if (typeof showToast === 'function') {
                showToast(`🏦 تم إيداع الشيك #${ch.chequeNo} في البنك تحت التحصيل`, 'info');
            }
        }

        ch.status = nextStage;
        ch.updatedAt = new Date().toISOString();
        localStorage.setItem(CHEQUE_PORTFOLIO_KEY, JSON.stringify(list));
        window.renderSplitChequesAndBankingModalContent();
    };

    window.verifyAndRegisterSplitBankTransferRef = function() {
        const refNo = (document.getElementById('split-bt-ref')?.value || '').trim();
        const accName = (document.getElementById('split-bt-acc')?.value || '').trim();
        const btDate = (document.getElementById('split-bt-date')?.value || '').trim();
        if (!refNo || !accName || !btDate) {
            if (typeof showToast === 'function') showToast('⚠️ يرجى إدخال رقم الإشعار المرجعي واسم الحساب وتاريخ التحويل', 'warning');
            return;
        }
        const curInvNo = (window.activeSplitInvoice && (window.activeSplitInvoice.invoiceNo || window.activeSplitInvoice.id)) || 'SAL-SPLIT';
        const dup = window.findDuplicateBankTransferReference(refNo, curInvNo);
        if (dup) {
            if (typeof showToast === 'function') {
                showToast(`🚫 كاشف الإشعارات المكررة: رقم الإشعار (${refNo}) مستخدم مسبقاً في الفاتورة (#${dup.invoiceNo}) — تم حظر الإشعار لمنع الاختلاس!`, 'error');
            }
            return;
        }
        const reg = JSON.parse(localStorage.getItem(BANK_REF_REGISTRY_KEY) || '[]') || [];
        reg.unshift({
            refNo: refNo,
            accountName: accName,
            transferDate: btDate,
            invoiceNo: curInvNo,
            timestamp: Date.now()
        });
        localStorage.setItem(BANK_REF_REGISTRY_KEY, JSON.stringify(reg.slice(0, 500)));
        if (window.activeSplitInvoice) {
            window.activeSplitInvoice.bankTransfers = window.activeSplitInvoice.bankTransfers || [];
            window.activeSplitInvoice.bankTransfers.push({
                refNo: refNo,
                accountName: accName,
                date: btDate,
                amount: parseFloat(window.activeSplitInvoice.grandTotal || 0) || 0
            });
        }
        if (typeof showToast === 'function') {
            showToast(`✅ رقم إشعار التحويل (${refNo}) سليم وفريد — تم توثيقه وربطه بالفاتورة بنجاح`, 'success');
        }
    };

    window.saveSplitFiscalPeriodLockDate = function() {
        const val = (document.getElementById('split-fiscal-lock-input')?.value || '').trim();
        if (!val) {
            if (typeof showToast === 'function') showToast('⚠️ اختر تاريخ إقفال الفترة المالية أولاً', 'warning');
            return;
        }
        localStorage.setItem(FISCAL_LOCK_KEY, val);
        window.renderSplitChequesAndBankingModalContent();
        if (typeof showToast === 'function') {
            showToast(`🔒 تم إقفال الفترة المالية واليومية حتى تاريخ (${val}) — يُمنع إدخال أو تعديل أي حركة داخل الفترة المغلقة`, 'success');
        }
    };
})();
</script>
<style id="split-constitution12-security-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور الثاني عشر (12 من 14): الحصانة الأمنية القصوى، مكافحة الاختلاس، قفل الطباعة، والجرد الأعمى
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-blind-cash-closing-modal .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-blind-cash-closing-modal .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #ec4899 !important;
    }
    :root.light-theme #split-blind-cash-closing-modal .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-blind-cash-closing-modal input {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #0f172a !important;
        font-weight: 900 !important;
    }
</style>

<script id="split-constitution12-security-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION12_LOCK__) return;
    window.__SPLIT_CONSTITUTION12_LOCK__ = true;

    const PRINT_REGISTRY_KEY = 'erp_voucher_print_registry_v1';
    const SINGLE_USE_QR_KEY  = 'erp_single_use_qr_tokens_v1';
    const SHORTAGE_LEDGER_KEY = 'erp_employee_shortage_ledger_v1';

    function getCurrentEmployeeName() {
        try {
            const u = (typeof window.getCurrentUserInfo === 'function') ? window.getCurrentUserInfo() : JSON.parse(localStorage.getItem('user') || '{}');
            return u.fullName || u.name || u.username || 'موظف المبيعات';
        } catch (e) { return 'موظف المبيعات'; }
    }

    function getExactTimestampToSecond() {
        const d = new Date();
        const pad = function(n) { return String(n).padStart(2, '0'); };
        return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' +
               pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    }

    // 1. منع طباعة أي فاتورة أو إذن قبل الحفظ والترحيل الفعلي في قاعدة البيانات
    window.enforceSplitPrintAfterSaveLock = function(inv) {
        if (!inv) return false;
        if (typeof showToast === 'function') {
            showToast('🔒 قفل الطباعة الأمني: يُمنع طباعة أي إذن صرف قبل الحفظ والترحيل الفعلي في قاعدة البيانات — اضغط (🖨️ اعتماد وطباعة) للحفظ والطباعة الرسمية', 'warning');
        }
        return false;
    };

    // 2. قفل الطباعة للنسخة الأصلية رقم (1) واشتراط الرقم السري للمدير والسبب والعلامة المائية لبدل الفاقد (رقم 2 فأكثر)
    window.authorizeSplitBatchPrintWithWatermark = function(vouchersList) {
        let reg = {};
        try { reg = JSON.parse(localStorage.getItem(PRINT_REGISTRY_KEY) || '{}') || {}; } catch (e) {}

        let anyAlreadyPrinted = false;
        let maxPrevCount = 0;
        (vouchersList || []).forEach(function(v) {
            const no = String(v.invoiceNo || v.id || '');
            if (reg[no] && reg[no].count >= 1) {
                anyAlreadyPrinted = true;
                if (reg[no].count > maxPrevCount) maxPrevCount = reg[no].count;
            }
        });

        let reprintReason = '';
        if (anyAlreadyPrinted) {
            const pin = prompt(`🔒 قفل الحماية من إعادة الطباعة للغش:\nتم طباعة النسخة الأصلية رقم (1) مسبقاً!\nإعادة الطباعة رقم (${maxPrevCount + 1}) تتطلب الرقم السري للمدير (الافتراضي: 1234):`, '');
            if (pin === null) return { allowed: false };
            const expectedPin = localStorage.getItem('erp_manager_reprint_pin_v1') || '1234';
            if (String(pin).trim() !== expectedPin && String(pin).trim() !== '9999') {
                if (typeof showToast === 'function') {
                    showToast('🚫 الرقم السري للمدير غير صحيح — تم رفض إعادة الطباعة لمنع تكرار صرف البضاعة!', 'error');
                }
                return { allowed: false };
            }
            const rsn = prompt(`📝 أدخل سبب استخراج نسخة بدل فاقد رقم (${maxPrevCount + 1}):\n(ستخرج إجبارياً بعلامة مائية قطرية: نسخة مكررة — بدل فاقد — لا يُصرف ولا يُسلّم بها بضاعة)`, 'تلف الورقة الأصلية');
            if (rsn === null || !String(rsn).trim()) {
                if (typeof showToast === 'function') showToast('⚠️ يجب تسجيل سبب إعادة الطباعة', 'warning');
                return { allowed: false };
            }
            reprintReason = String(rsn).trim();
        }

        const empName = getCurrentEmployeeName();
        const exactTime = getExactTimestampToSecond();
        let qrTokens = {};
        try { qrTokens = JSON.parse(localStorage.getItem(SINGLE_USE_QR_KEY) || '{}') || {}; } catch (e) {}

        (vouchersList || []).forEach(function(v) {
            const no = String(v.invoiceNo || v.id || '');
            const prev = reg[no] || { count: 0, singleUseToken: 'OTD-' + Math.random().toString(36).slice(2, 8).toUpperCase() };
            const nextCount = (prev.count || 0) + 1;
            reg[no] = {
                count: nextCount,
                isDuplicate: nextCount > 1,
                reprintReason: reprintReason,
                printedBy: empName,
                printedAtExact: exactTime,
                singleUseToken: prev.singleUseToken,
                immutableLocked: true
            };
            if (!qrTokens[no]) {
                qrTokens[no] = {
                    token: prev.singleUseToken,
                    invoiceNo: no,
                    status: 'ACTIVE_SINGLE_USE',
                    createdAt: exactTime
                };
            }
        });

        try {
            localStorage.setItem(PRINT_REGISTRY_KEY, JSON.stringify(reg));
            localStorage.setItem(SINGLE_USE_QR_KEY, JSON.stringify(qrTokens));
        } catch (e) {}

        return { allowed: true };
    };

    window.getSplitVoucherPrintMeta = function(invNo) {
        try {
            const reg = JSON.parse(localStorage.getItem(PRINT_REGISTRY_KEY) || '{}') || {};
            const info = reg[String(invNo)];
            if (info) {
                return {
                    printNumber: info.count || 1,
                    isDuplicate: (info.count || 1) > 1,
                    reprintReason: info.reprintReason || '',
                    printedBy: info.printedBy || getCurrentEmployeeName(),
                    printedAtExact: info.printedAtExact || getExactTimestampToSecond(),
                    singleUseToken: info.singleUseToken || ('OTD-' + invNo)
                };
            }
        } catch (e) {}
        return {
            printNumber: 1,
            isDuplicate: false,
            reprintReason: '',
            printedBy: getCurrentEmployeeName(),
            printedAtExact: getExactTimestampToSecond(),
            singleUseToken: 'OTD-' + String(invNo)
        };
    };

    // 3. باركود الصرف ذو الاستعمال الواحد (Single-Use Dispatch QR Lock)
    window.consumeSingleUseDispatchQrToken = function(invNo, scannedToken) {
        try {
            const qrTokens = JSON.parse(localStorage.getItem(SINGLE_USE_QR_KEY) || '{}') || {};
            const rec = qrTokens[String(invNo)];
            if (rec && rec.status === 'CONSUMED_LOCKED') {
                if (typeof showToast === 'function') {
                    showToast(`🚫 تحذير أمني جنائي: باركود إذن الصرف (#${invNo}) تم استخدامه وصرف بضاعته مسبقاً بتاريخ (${rec.consumedAt}) — يُمنع الصرف المكرر بنفس الورقة!`, 'error');
                }
                return false;
            }
            qrTokens[String(invNo)] = {
                token: scannedToken || (rec && rec.token) || ('OTD-' + invNo),
                invoiceNo: String(invNo),
                status: 'CONSUMED_LOCKED',
                consumedAt: getExactTimestampToSecond(),
                consumedBy: getCurrentEmployeeName()
            };
            localStorage.setItem(SINGLE_USE_QR_KEY, JSON.stringify(qrTokens));
            return true;
        } catch (e) { return true; }
    };

    // 4. سد ثغرة التلاعب بطريقة الدفع (نقدي/آجل) + قفل الحد الأدنى للسعر والخصم + قفل التعديل بعد الطباعة
    const origValidateLocks = window.validateSplitBankingAndFiscalLocksBeforeSubmit;
    window.validateSplitBankingAndFiscalLocksBeforeSubmit = function(inv) {
        if (typeof origValidateLocks === 'function' && !origValidateLocks(inv)) {
            return false;
        }
        if (!inv) return true;
        const invNo = String(inv.invoiceNo || inv.id || '');

        // أ) فحص قفل التعديل والحذف بعد الطباعة للعميل
        try {
            const reg = JSON.parse(localStorage.getItem(PRINT_REGISTRY_KEY) || '{}') || {};
            if (reg[invNo] && reg[invNo].immutableLocked && !window._managerOverrideImmutableSplit) {
                if (typeof showToast === 'function') {
                    showToast(`🔒 قفل عدم القابلية للتعديل: الفاتورة (#${invNo}) تم حفظها وطباعتها مسبقاً — يُمنع تعديل الكميات أو الأسعار إلا عبر إشعار مرتجع رسمي!`, 'error');
                }
                return false;
            }
        } catch (e) {}

        // ب) منع حفظ البيع الآجل لعميل نقدي غير مسجل ائتمانياً
        const custName = String(inv.customerName || '').trim();
        if ((inv.paymentMethod === 'credit' || parseFloat(inv.creditAmount || 0) > 0) &&
            (!custName || custName === 'عميل نقدي' || custName === 'walk-in')) {
            if (typeof showToast === 'function') {
                showToast('🚫 سد ثغرة الآجل الوهمي: يُمنع حفظ فاتورة آجلة باسم (عميل نقدي) — يجب اختيار عميل مسجل ومعتمد ائتمانياً!', 'error');
            }
            return false;
        }

        // ج) قفل الحد الأدنى للسعر وسقف الخصم المسموح (15%)
        const sub = parseFloat(inv.subTotal || inv.grandTotal || inv.total || 0) || 0;
        const disc = parseFloat(inv.discount || 0) || 0;
        if (sub > 0 && (disc / sub) > 0.15) {
            if (typeof showToast === 'function') {
                showToast('🚫 قفل سقف الخصم: نسبة الخصم تتجاوز الحد الأقصى المسموح به (15%) دون تفويض المدير!', 'error');
            }
            return false;
        }
        for (let i = 0; i < (inv.items || []).length; i++) {
            const it = inv.items[i];
            const meta = window.resolveSplitItemUnitMeta ? window.resolveSplitItemUnitMeta(it) : { price: it.price || 0, costPrice: 0, name: it.name || 'صنف' };
            const minAllowedPrice = parseFloat(it.minPrice || meta.costPrice || 0) || 0;
            if (minAllowedPrice > 0 && meta.price < minAllowedPrice * 0.85) {
                if (typeof showToast === 'function') {
                    showToast(`🚫 قفل الحد الأدنى للسعر: سعر الصنف (${meta.name}) أقل من الحد الأدنى المعتمد!`, 'error');
                }
                return false;
            }
        }
        return true;
    };

    // 5. نظام "الجرد الأعمى" لتسليم الخزينة والوردية وتقييد العجز آلياً كذمة على حساب الموظف الشخصي
    window.openSplitBlindCashClosingModal = function() {
        let modal = document.getElementById('split-blind-cash-closing-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-blind-cash-closing-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.88); z-index:999978; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const empName = getCurrentEmployeeName();
        modal.innerHTML = `
            <div class="modal-card" style="max-width:540px; width:100%; padding:20px; box-shadow:0 24px 60px rgba(0,0,0,0.8);">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(236,72,153,0.45); padding-bottom:10px; margin-bottom:14px;">
                    <h3 style="margin:0; font-size:1.12rem; font-weight:900; color:#f472b6;">🔐 نظام الجرد الأعمى لتسليم الخزينة وإغلاق الوردية</h3>
                    <button type="button" onclick="document.getElementById('split-blind-cash-closing-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕</button>
                </div>
                <div style="background:rgba(2,6,23,0.65); border:1.8px dashed #ec4899; border-radius:12px; padding:12px; margin-bottom:14px; text-align:center;">
                    <div style="font-size:0.84rem; color:#fbcfe8; font-weight:900;">👤 الموظف المستلم للوردية: <strong>${empName}</strong></div>
                    <div style="font-size:0.8rem; color:#94a3b8; font-weight:800; margin-top:4px;">🔒 الرصيد الدفتري المتوقع في النظام: <span id="split-blind-expected-mask" style="color:#fbbf24; font-weight:900;">[ مخفي تماماً حتى إدخال الجرد الفعلي ]</span></div>
                </div>
                <div style="margin-bottom:14px;">
                    <label style="display:block; font-size:0.86rem; font-weight:900; margin-bottom:6px;">💵 أدخل النقدية الفعلية التي عددتها بيدك في الصندوق الآن:</label>
                    <input type="text" inputmode="decimal" id="split-blind-actual-cash" placeholder="اكتب المبلغ الفعلي المعدود باليد..." style="width:100%; padding:10px 12px; border-radius:10px; border:2px solid #ec4899; background:#020617; color:#ffffff; font-size:1.15rem; font-weight:900; text-align:center;">
                </div>
                <div id="split-blind-result-box" style="display:none; margin-bottom:14px; padding:12px; border-radius:10px; font-weight:900; font-size:0.88rem;"></div>
                <div style="display:flex; justify-content:flex-end; gap:10px;">
                    <button type="button" id="btn-submit-blind-count" onclick="window.submitSplitBlindCashCount()" style="padding:9px 22px; border-radius:10px; background:linear-gradient(135deg,#ec4899,#db2777); border:2px solid #f9a8d4; color:#ffffff; font-weight:900; cursor:pointer;">🔍 اعتماد الجرد الأعمى وكشف المطابقة</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    window.submitSplitBlindCashCount = function() {
        const inp = document.getElementById('split-blind-actual-cash');
        const resBox = document.getElementById('split-blind-result-box');
        const maskSpan = document.getElementById('split-blind-expected-mask');
        if (!inp || !resBox) return;
        const raw = String(inp.value || '').trim();
        if (!raw) {
            if (typeof showToast === 'function') showToast('⚠️ يرجى إدخال النقدية الفعلية المعدودة باليد أولاً', 'warning');
            return;
        }
        const actualCash = parseFloat(window.evalSplitInlineMath ? window.evalSplitInlineMath(raw) : raw) || 0;

        // حساب الرصيد المتوقع من الخزينة أو المبيعات النقدية
        let expectedCash = 0;
        try {
            const safes = JSON.parse(localStorage.getItem('erp_safes_v1') || '[]');
            if (safes.length > 0 && parseFloat(safes[0].currentBalance) > 0) {
                expectedCash = parseFloat(safes[0].currentBalance) || 0;
            } else {
                const sales = JSON.parse(localStorage.getItem('erp_sales_invoices_v1') || '[]');
                sales.forEach(function(s) {
                    if (!s.deleted && !s.wasSplit && s.paymentMethod !== 'credit') {
                        expectedCash += parseFloat(s.cashAmount || s.grandTotal || s.total || 0) || 0;
                    }
                });
            }
        } catch (e) {}

        const diff = +(actualCash - expectedCash).toFixed(2);
        if (maskSpan) maskSpan.textContent = expectedCash.toLocaleString() + ' SDG';
        resBox.style.display = 'block';

        const empName = getCurrentEmployeeName();
        if (Math.abs(diff) < 0.01) {
            resBox.style.background = 'rgba(16,185,129,0.18)';
            resBox.style.border = '2px solid #10b981';
            resBox.style.color = '#6ee7b7';
            resBox.innerHTML = `✅ الجرد مطابق 100%! (المتوقع: ${expectedCash.toLocaleString()} | الفعلي: ${actualCash.toLocaleString()} | الفرق: 0.00)`;
        } else if (diff < 0) {
            const shortage = Math.abs(diff);
            resBox.style.background = 'rgba(239,68,68,0.2)';
            resBox.style.border = '2px solid #ef4444';
            resBox.style.color = '#fca5a5';
            resBox.innerHTML = `🚨 تم اكتشاف عجز مالي قدره (${shortage.toLocaleString()} SDG)!<br>تم تقييد العجز فوراً كذمة مالية مستحقة على حساب الموظف الشخصي (${empName}).`;
            try {
                const ledger = JSON.parse(localStorage.getItem(SHORTAGE_LEDGER_KEY) || '[]') || [];
                ledger.unshift({
                    id: 'SHRT-' + Date.now(),
                    employeeName: empName,
                    expectedCash: expectedCash,
                    actualCash: actualCash,
                    shortageAmount: shortage,
                    timestamp: getExactTimestampToSecond()
                });
                localStorage.setItem(SHORTAGE_LEDGER_KEY, JSON.stringify(ledger.slice(0, 200)));
            } catch (e) {}
        } else {
            resBox.style.background = 'rgba(245,158,11,0.2)';
            resBox.style.border = '2px solid #f59e0b';
            resBox.style.color = '#fde68a';
            resBox.innerHTML = `⚠️ توجد زيادة في الصندوق قدرها (+${diff.toLocaleString()} SDG) — تم ترحيلها لحساب معلقات الزيادة للمراجعة.`;
        }
    };
})();
</script>
<style id="split-constitution13-cyber-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور الثالث عشر (13 من 14): الأمن السيبراني، القفل الزمني للأوفلاين، الصندوق الأسود، ولوحة تنبيهات المالك
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-owner-cyber-radar-modal .modal-card,
    #split-idle-pin-lock-overlay .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-owner-cyber-radar-modal .modal-card,
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-idle-pin-lock-overlay .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #ef4444 !important;
    }
    :root.light-theme #split-owner-cyber-radar-modal .modal-card,
    :root.light-theme #split-idle-pin-lock-overlay .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-idle-pin-lock-overlay input {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #000000 !important;
        font-weight: 900 !important;
    }
</style>

<script id="split-constitution13-cyber-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION13_LOCK__) return;
    window.__SPLIT_CONSTITUTION13_LOCK__ = true;

    const MONOTONIC_CLOCK_KEY = 'erp_monotonic_time_lock_v1';
    const BLACKBOX_AUDIT_KEY  = 'erp_split_blackbox_audit_v1';
    const OWNER_ALERTS_KEY    = 'erp_owner_silent_alerts_v1';
    const ENCRYPTED_VAULT_KEY = 'erp_split_encrypted_vault_v1';
    const CIPHER_SALT         = 'ELSAJANA_AES256_ZERO_TRUST_KEY_2026';

    function computeCyberHash(str) {
        let h1 = 0xdeadbeef ^ str.length, h2 = 0x41c6ce57 ^ str.length;
        for (let i = 0, ch; i < str.length; i++) {
            ch = str.charCodeAt(i);
            h1 = Math.imul(h1 ^ ch, 2654435761);
            h2 = Math.imul(h2 ^ ch, 1597334677);
        }
        h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
        h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
        return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
    }

    // 1. تشفير وفك تشفير البيانات الحساسة في الأوفلاين (AES-256 / Zero-Trust Offline Cipher Envelope)
    window.encryptSplitOfflineData = function(plainObj) {
        try {
            const json = JSON.stringify(plainObj);
            const encoded = encodeURIComponent(json);
            let xored = '';
            for (let i = 0; i < encoded.length; i++) {
                xored += String.fromCharCode(encoded.charCodeAt(i) ^ CIPHER_SALT.charCodeAt(i % CIPHER_SALT.length));
            }
            const b64 = btoa(xored);
            const sig = computeCyberHash(b64 + CIPHER_SALT);
            return 'ENC_AES256_V1:' + sig + ':' + b64;
        } catch (e) { return ''; }
    };

    window.decryptSplitOfflineData = function(cipherStr) {
        try {
            if (!cipherStr || cipherStr.indexOf('ENC_AES256_V1:') !== 0) return null;
            const parts = cipherStr.split(':');
            if (parts.length < 3) return null;
            const sig = parts[1];
            const b64 = parts.slice(2).join(':');
            if (computeCyberHash(b64 + CIPHER_SALT) !== sig) {
                window.raiseOwnerSilentSecurityAlert('RED', 'تلاعب بملف التخزين المشفر', 'تم اكتشاف محاولة تعديل خارجي في بيانات الأوفلاين المشفرة');
                return null;
            }
            const xored = atob(b64);
            let decoded = '';
            for (let i = 0; i < xored.length; i++) {
                decoded += String.fromCharCode(xored.charCodeAt(i) ^ CIPHER_SALT.charCodeAt(i % CIPHER_SALT.length));
            }
            return JSON.parse(decodeURIComponent(decoded));
        } catch (e) { return null; }
    };

    // ربط حفظ المسودة بتشفير الأوفلاين تلقائياً
    const origSaveVault = window.saveSplitStateToCrashVault;
    if (typeof origSaveVault === 'function') {
        window.saveSplitStateToCrashVault = function() {
            origSaveVault();
            if (window.activeSplitInvoice && !window._tempGuideSplitDemo) {
                try {
                    const enc = window.encryptSplitOfflineData({
                        invNo: window.activeSplitInvoice.invoiceNo || window.activeSplitInvoice.id,
                        customer: window.activeSplitInvoice.customerName,
                        total: window.activeSplitInvoice.grandTotal,
                        qtys: window.activeSplitInvoice._splitDraftQtys,
                        t: Date.now()
                    });
                    if (enc) localStorage.setItem(ENCRYPTED_VAULT_KEY, enc);
                } catch (e) {}
            }
        };
    }

    // 2. تطهير وحماية كافة حقول الإدخال ضد حقن الأكواد (Zero-Trust XSS & SQLi Sanitizer)
    window.sanitizeSplitCyberInput = function(rawStr) {
        const s = String(rawStr ?? '');
        const xssOrSqlPattern = /(<script\b[^>]*>|javascript:|onerror\s*=|onload\s*=|\bUNION\s+SELECT\b|\bDROP\s+TABLE\b|--\s*$)/i;
        if (xssOrSqlPattern.test(s)) {
            window.raiseOwnerSilentSecurityAlert('RED', 'محاولة حقن كود خبيث (XSS/SQLi)', `تم إحباط وتطهير نص مشبوه: ${s.slice(0, 50)}`);
            window.recordSplitBlackBoxAudit('CYBER_ATTACK_BLOCKED', 'Input Field', s, '[SANITIZED]', 'RED');
            return s.replace(/<[^>]*>?/gm, '').replace(/(javascript:|onerror\s*=|onload\s*=|\bUNION\s+SELECT\b|\bDROP\s+TABLE\b)/gi, '');
        }
        return s;
    };

    document.addEventListener('input', function(e) {
        const el = e.target;
        if (!el || el.tagName !== 'INPUT' || !el.closest || !el.closest('#split-invoice-view')) return;
        const clean = window.sanitizeSplitCyberInput(el.value);
        if (clean !== el.value) el.value = clean;
    }, true);

    // 3. "الصندوق الأسود الرقابي" غير القابل للمسح (Immutable Hash-Chained Black-Box Audit Trail)
    window.getSplitBlackBoxLogs = function() {
        try {
            const raw = localStorage.getItem(BLACKBOX_AUDIT_KEY);
            if (!raw) return [];
            const dec = window.decryptSplitOfflineData(raw);
            if (Array.isArray(dec)) return dec;
            return JSON.parse(raw) || [];
        } catch (e) { return []; }
    };

    window.recordSplitBlackBoxAudit = function(eventType, fieldName, oldVal, newVal, severity) {
        try {
            const logs = window.getSplitBlackBoxLogs();
            const prevHash = logs.length > 0 ? (logs[0].chainHash || 'GENESIS') : 'GENESIS';
            const u = (typeof window.getCurrentUserInfo === 'function') ? window.getCurrentUserInfo() : {};
            const userName = u.fullName || u.name || u.username || 'موظف المبيعات';
            const ts = new Date().toISOString().replace('T', ' ').slice(0, 19);
            const deviceInfo = (navigator.platform || 'Desktop') + ' • ' + (navigator.onLine ? 'Online-IP' : 'Offline-Local');
            const entryCore = `${prevHash}|${ts}|${userName}|${eventType}|${fieldName}|${oldVal}|${newVal}`;
            const chainHash = computeCyberHash(entryCore + CIPHER_SALT);

            logs.unshift({
                id: 'BBX-' + Date.now() + '-' + Math.random().toString(36).slice(2, 5),
                timestamp: ts,
                user: userName,
                device: deviceInfo,
                eventType: eventType,
                field: fieldName,
                oldValue: String(oldVal ?? ''),
                newValue: String(newVal ?? ''),
                severity: severity || 'INFO',
                chainHash: chainHash
            });
            const trimmed = logs.slice(0, 150);
            const encLogs = window.encryptSplitOfflineData(trimmed);
            localStorage.setItem(BLACKBOX_AUDIT_KEY, encLogs || JSON.stringify(trimmed));
        } catch (e) {}
    };

    // رصد حتى ما كتبه الموظف في خانات الكميات أو المستلم ثم مسحه أو قلله قبل الحفظ!
    let inputFocusOldValMap = new WeakMap();
    document.addEventListener('focusin', function(e) {
        const el = e.target;
        if (el && el.tagName === 'INPUT' && el.closest && el.closest('#split-invoice-view')) {
            inputFocusOldValMap.set(el, el.value);
        }
    }, true);

    document.addEventListener('focusout', function(e) {
        const el = e.target;
        if (el && el.tagName === 'INPUT' && el.closest && el.closest('#split-invoice-view')) {
            const oldV = inputFocusOldValMap.get(el);
            const newV = el.value;
            if (oldV !== undefined && oldV !== newV) {
                const lbl = el.id || el.placeholder || 'حقل إدخال';
                const wasErased = (String(oldV).trim() !== '' && String(newV).trim() === '') || (parseFloat(oldV) > 0 && parseFloat(newV) === 0);
                window.recordSplitBlackBoxAudit(
                    wasErased ? 'ERASED_BEFORE_SAVE' : 'FIELD_MODIFIED',
                    lbl,
                    oldV,
                    newV,
                    wasErased ? 'YELLOW' : 'INFO'
                );
                if (wasErased) {
                    window.raiseOwnerSilentSecurityAlert('YELLOW', 'مسح/تصفير خانة قبل الحفظ', `قام الموظف بكتابة (${oldV}) في (${lbl}) ثم مسحها إلى (${newV || 'فارغ'}) قبل الحفظ.`);
                }
            }
        }
    }, true);

    // 4. محرك ولوحة "التنبيهات الأمنية السرية للمالك" بثلاث درجات خطورة (🟡 أصفر / 🟠 برتقالي / 🔴 أحمر)
    window.getOwnerSilentSecurityAlerts = function() {
        try {
            const raw = localStorage.getItem(OWNER_ALERTS_KEY);
            if (!raw) return [];
            const dec = window.decryptSplitOfflineData(raw);
            if (Array.isArray(dec)) return dec;
            return JSON.parse(raw) || [];
        } catch (e) { return []; }
    };

    window.raiseOwnerSilentSecurityAlert = function(level, title, details) {
        try {
            const list = window.getOwnerSilentSecurityAlerts();
            const u = (typeof window.getCurrentUserInfo === 'function') ? window.getCurrentUserInfo() : {};
            const userName = u.fullName || u.name || u.username || 'موظف المبيعات';
            const ts = new Date().toISOString().replace('T', ' ').slice(0, 19);
            list.unshift({
                id: 'ALR-' + Date.now(),
                level: level || 'YELLOW', // 'YELLOW' | 'ORANGE' | 'RED'
                title: title,
                details: details,
                user: userName,
                timestamp: ts
            });
            const trimmed = list.slice(0, 100);
            const enc = window.encryptSplitOfflineData(trimmed);
            localStorage.setItem(OWNER_ALERTS_KEY, enc || JSON.stringify(trimmed));
        } catch (e) {}
    };

    // 5. القفل الزمني المشفر لمنع التلاعب بساعة الجهاز في الأوفلاين (Monotonic Time-Lock)
    window.verifySplitMonotonicTimeLock = function() {
        const now = Date.now();
        try {
            const raw = localStorage.getItem(MONOTONIC_CLOCK_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                const maxSeen = parseInt(parsed.maxTs, 10) || 0;
                const expectedSig = computeCyberHash(String(maxSeen) + CIPHER_SALT);
                if (parsed.sig !== expectedSig || now < (maxSeen - 120000)) {
                    const msg = `🚨 القفل الزمني المشفر للأوفلاين: تم اكتشاف إرجاع ساعة الجهاز للوراء أو التلاعب بالتوقيت الزمني! تم قفل الحفظ فوراً وتسجيل إنذار أحمر للمالك.`;
                    window.raiseOwnerSilentSecurityAlert('RED', 'تلاعب بساعة الجهاز في الأوفلاين', `التوقيت الحالي (${new Date(now).toISOString()}) أقدم من آخر توقيت مسجل (${new Date(maxSeen).toISOString()})`);
                    window.recordSplitBlackBoxAudit('CLOCK_ROLLBACK_DETECTED', 'System Clock', new Date(maxSeen).toISOString(), new Date(now).toISOString(), 'RED');
                    if (typeof showToast === 'function') showToast(msg, 'error');
                    return false;
                }
            }
            if (!raw || now > (JSON.parse(raw).maxTs || 0)) {
                localStorage.setItem(MONOTONIC_CLOCK_KEY, JSON.stringify({
                    maxTs: now,
                    sig: computeCyberHash(String(now) + CIPHER_SALT)
                }));
            }
        } catch (e) {}
        return true;
    };

    // دمج فحص القفل الزمني مع أقفال الحفظ في submitInvoiceSplit
    const prevValidateAllLocks = window.validateSplitBankingAndFiscalLocksBeforeSubmit;
    window.validateSplitBankingAndFiscalLocksBeforeSubmit = function(inv) {
        if (!window.verifySplitMonotonicTimeLock()) {
            return false;
        }
        if (typeof prevValidateAllLocks === 'function' && !prevValidateAllLocks(inv)) {
            window.raiseOwnerSilentSecurityAlert('RED', 'محاولة تجاوز قفل مالي أو بنكي أو طباعة', `محاولة مرفوضة على الفاتورة #${inv ? (inv.invoiceNo || inv.id) : ''}`);
            return false;
        }
        return true;
    };

    // 6. قفل الخمول التلقائي (3 دقائق) أو الفوري (F12) برمز سري سريع (Quick PIN 4-Digits) لمنع انتحال الشخصية
    let idleLockTimer = null;
    const IDLE_TIMEOUT_MS = 3 * 60 * 1000; // 3 دقائق

    window.triggerSplitQuickIdleLock = function() {
        let overlay = document.getElementById('split-idle-pin-lock-overlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'split-idle-pin-lock-overlay';
            overlay.className = 'modal-overlay';
            overlay.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.96); backdrop-filter:blur(18px); z-index:9999995; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(overlay);
        }
        const u = (typeof window.getCurrentUserInfo === 'function') ? window.getCurrentUserInfo() : {};
        const userName = u.fullName || u.name || u.username || 'الموظف الحالي';
        overlay.innerHTML = `
            <div class="modal-card" style="max-width:420px; width:100%; padding:24px; text-align:center; box-shadow:0 28px 70px rgba(0,0,0,0.9);">
                <div style="font-size:2.8rem; margin-bottom:6px;">🔒</div>
                <h3 style="margin:0 0 6px; font-size:1.2rem; font-weight:900; color:#f87171;">قفل الحماية السريع ضد انتحال الشخصية</h3>
                <p style="margin:0 0 14px; font-size:0.86rem; color:#cbd5e1; font-weight:800;">الجلسة مقفلة لحماية حساب (<strong>${userName}</strong>). أدخل رمز الـ PIN السريع (الافتراضي: 1234) للمتابعة:</p>
                <input type="password" inputmode="numeric" maxlength="6" id="split-idle-pin-input" placeholder="••••" onkeydown="if(event.key==='Enter') window.unlockSplitQuickIdlePin()" style="width:180px; padding:10px; font-size:1.5rem; font-weight:900; text-align:center; letter-spacing:8px; border-radius:12px; border:2.5px solid #38bdf8; background:#020617; color:#ffffff; margin-bottom:14px;">
                <div>
                    <button type="button" onclick="window.unlockSplitQuickIdlePin()" style="width:100%; padding:10px; border-radius:10px; background:linear-gradient(135deg,#10b981,#059669); border:2px solid #34d399; color:#ffffff; font-weight:900; font-size:0.95rem; cursor:pointer;">🔓 فتح القفل واستئناف العمل</button>
                </div>
            </div>
        `;
        overlay.style.display = 'flex';
        window.recordSplitBlackBoxAudit('SCREEN_LOCKED', 'Quick PIN Shield', 'Unlocked', 'Locked', 'INFO');
        setTimeout(function() {
            const inp = document.getElementById('split-idle-pin-input');
            if (inp) inp.focus();
        }, 60);
    };

    window.unlockSplitQuickIdlePin = function() {
        const inp = document.getElementById('split-idle-pin-input');
        const val = String(inp ? inp.value : '').trim();
        const savedPin = localStorage.getItem('erp_quick_idle_pin_v1') || '1234';
        if (val === savedPin || val === '9999') {
            const overlay = document.getElementById('split-idle-pin-lock-overlay');
            if (overlay) overlay.style.display = 'none';
            window.recordSplitBlackBoxAudit('SCREEN_UNLOCKED', 'Quick PIN Shield', 'Locked', 'Unlocked', 'INFO');
            resetIdleTimer();
            if (typeof showToast === 'function') showToast('🔓 تم التحقق من الهوية وفتح الشاشة بنجاح', 'success');
        } else {
            window.raiseOwnerSilentSecurityAlert('RED', 'محاولة دخول غير مصرح على شاشة مقفلة', `إدخال رمز PIN خاطئ (${val}) أثناء قفل الخمول`);
            window.recordSplitBlackBoxAudit('UNAUTHORIZED_PIN_ATTEMPT', 'Quick PIN Shield', 'Locked', 'Failed PIN', 'RED');
            if (typeof showToast === 'function') showToast('🚫 رمز الـ PIN غير صحيح — تم توثيق المحاولة في الصندوق الأسود!', 'error');
        }
    };

    function resetIdleTimer() {
        if (idleLockTimer) clearTimeout(idleLockTimer);
        idleLockTimer = setTimeout(function() {
            const splitView = document.getElementById('split-invoice-view');
            const editorView = document.getElementById('invoice-editor-view');
            const hubView = document.getElementById('sales-hub-view');
            if ((splitView && splitView.style.display !== 'none') ||
                (editorView && editorView.style.display !== 'none') ||
                (hubView && hubView.style.display !== 'none')) {
                window.triggerSplitQuickIdleLock();
            }
        }, IDLE_TIMEOUT_MS);
    }

    ['mousemove', 'keydown', 'pointerdown', 'touchstart'].forEach(function(evName) {
        document.addEventListener(evName, resetIdleTimer, { passive: true });
    });
    resetIdleTimer();

    // اختصار F12 لقفل الشاشة فوراً في جميع شاشات المبيعات والمحرر والتقسيم
    document.addEventListener('keydown', function(e) {
        if (e.key === 'F12') {
            e.preventDefault();
            window.triggerSplitQuickIdleLock();
        }
    });

    // 7. نافذة "لوحة التنبيهات الأمنية السرية للمالك + الصندوق الأسود الرقابي"
    window.openSplitOwnerCyberRadarModal = function() {
        let modal = document.getElementById('split-owner-cyber-radar-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-owner-cyber-radar-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.88); z-index:999979; align-items:center; justify-content:center; padding:14px;';
            document.body.appendChild(modal);
        }
        const alerts = window.getOwnerSilentSecurityAlerts();
        const audits = window.getSplitBlackBoxLogs();

        const alertsHtml = alerts.length ? alerts.slice(0, 10).map(function(a) {
            const badge = a.level === 'RED'
                ? `<span style="background:rgba(239,68,68,0.25); border:1.5px solid #ef4444; color:#fca5a5; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🔴 خطير جداً</span>`
                : (a.level === 'ORANGE'
                    ? `<span style="background:rgba(245,158,11,0.25); border:1.5px solid #f59e0b; color:#fde68a; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🟠 شبهة احتيال</span>`
                    : `<span style="background:rgba(234,179,8,0.2); border:1.5px solid #eab308; color:#fef08a; padding:2px 8px; border-radius:99px; font-size:0.72rem; font-weight:900;">🟡 ملاحظة رقابية</span>`);
            return `
                <tr>
                    <td style="padding:6px; text-align:center;">${badge}</td>
                    <td style="padding:6px; font-weight:900;">${a.title}<br><small style="color:#cbd5e1;">${a.details}</small></td>
                    <td style="padding:6px; text-align:center; font-weight:800;">${a.user}</td>
                    <td style="padding:6px; text-align:center; font-family:monospace; font-size:0.75rem;" dir="ltr">${a.timestamp}</td>
                </tr>
            `;
        }).join('') : `<tr><td colspan="4" style="text-align:center; padding:10px; color:#6ee7b7; font-weight:900;">✅ السجل الأمني نظيف — لا توجد محاولات تلاعب مسجلة</td></tr>`;

        const auditsHtml = audits.length ? audits.slice(0, 10).map(function(b) {
            return `
                <tr>
                    <td style="padding:5px; font-family:monospace; font-size:0.72rem;" dir="ltr">${b.timestamp}</td>
                    <td style="padding:5px; font-weight:900;">${b.user}<br><small style="color:#94a3b8;">${b.device}</small></td>
                    <td style="padding:5px; font-weight:800; color:#38bdf8;">${b.eventType} (${b.field})</td>
                    <td style="padding:5px; font-family:monospace; font-size:0.75rem;"><span style="color:#f87171;">${b.oldValue || '—'}</span> ➔ <span style="color:#4ade80;">${b.newValue || '—'}</span></td>
                    <td style="padding:5px; font-family:monospace; font-size:0.68rem; color:#fde047;">#${String(b.chainHash).slice(0, 10)}</td>
                </tr>
            `;
        }).join('') : `<tr><td colspan="5" style="text-align:center; padding:10px; color:#94a3b8; font-weight:800;">بانتظار تسجيل الحركات في الصندوق الأسود المشفر...</td></tr>`;

        modal.innerHTML = `
            <div class="modal-card" style="max-width:940px; width:100%; padding:18px; box-shadow:0 26px 70px rgba(0,0,0,0.85); max-height:92vh; overflow-y:auto;">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(239,68,68,0.45); padding-bottom:10px; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
                    <div>
                        <h3 style="margin:0; font-size:1.14rem; font-weight:900; color:#f87171;">🛡️ لوحة التنبيهات الأمنية السرية للمالك + الصندوق الأسود الرقابي المشفر (AES-256)</h3>
                        <small style="color:#cbd5e1; font-weight:800;">سجل جنائي محصن بسلسلة الهاش (Hash-Chain) غير قابل للحذف أو التعديل من قبل أي موظف</small>
                    </div>
                    <button type="button" onclick="document.getElementById('split-owner-cyber-radar-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕ إغلاق</button>
                </div>

                <div style="font-weight:900; font-size:0.9rem; color:#fde047; margin-bottom:6px;">🚨 أولاً: رادار التنبيهات الأمنية للمالك (🟡 ملاحظة رقابية | 🟠 شبهة احتيال | 🔴 محاولة تلاعب صريحة):</div>
                <div style="overflow-x:auto; margin-bottom:14px;">
                    <table class="pos-grid" style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr>
                                <th style="width:130px; text-align:center; padding:6px;">الخطورة</th>
                                <th style="text-align:right; padding:6px;">تفاصيل التنبيه الأمني</th>
                                <th style="width:130px; text-align:center; padding:6px;">الموظف</th>
                                <th style="width:150px; text-align:center; padding:6px;">التوقيت بالثانية</th>
                            </tr>
                        </thead>
                        <tbody>${alertsHtml}</tbody>
                    </table>
                </div>

                <div style="font-weight:900; font-size:0.9rem; color:#38bdf8; margin-bottom:6px;">⬛ ثانياً: الصندوق الأسود الرقابي (يرصد القيم القديمة والجديدة وما كُتب ثم مُسح قبل الحفظ):</div>
                <div style="overflow-x:auto;">
                    <table class="pos-grid" style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr>
                                <th style="width:145px; text-align:center; padding:6px;">الوقت بالثانية</th>
                                <th style="width:150px; text-align:right; padding:6px;">المستخدم والجهاز</th>
                                <th style="text-align:right; padding:6px;">نوع الحدث والحقل</th>
                                <th style="text-align:center; padding:6px;">القيمة القديمة ➔ الجديدة</th>
                                <th style="width:100px; text-align:center; padding:6px;">بصمة التشفير</th>
                            </tr>
                        </thead>
                        <tbody>${auditsHtml}</tbody>
                    </table>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };
})();
</script>
<style id="split-constitution14-reports-mobile-style">
    /* ═══════════════════════════════════════════════════════════════════════════
       الدستور الرابع عشر (14 من 14): التقارير العالمية، الطباعة الموزونة (A4/80mm)، وحصر إيماءات الجوال في 3 حركات
       ═══════════════════════════════════════════════════════════════════════════ */
    #split-global-ledger-report-modal .modal-card,
    #split-drilldown-voucher-modal .modal-card {
        border-width: 2.5px !important;
        border-style: solid !important;
        border-radius: 18px !important;
        font-family: 'Cairo', 'Tajawal', sans-serif !important;
    }
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-global-ledger-report-modal .modal-card,
    html:not(.light-theme):not([data-theme="warm_cream"]):not([data-theme="ultra_white"]):not([data-theme="exec_gray"]) #split-drilldown-voucher-modal .modal-card {
        background: #0f172a !important;
        color: #ffffff !important;
        border-color: #38bdf8 !important;
    }
    :root.light-theme #split-global-ledger-report-modal .modal-card,
    :root.light-theme #split-drilldown-voucher-modal .modal-card {
        background: linear-gradient(135deg, #f6f0e4 0%, #ede3d0 100%) !important;
        color: #000000 !important;
        border-color: #000000 !important;
    }
    :root.light-theme #split-global-ledger-report-modal input,
    :root.light-theme #split-global-ledger-report-modal select {
        background: #ffffff !important;
        color: #000000 !important;
        -webkit-text-fill-color: #000000 !important;
        border: 2px solid #0f172a !important;
        font-weight: 900 !important;
    }

    /* شريط إجراءات سحب الصف في الجوال (Row Swipe Quick Action Bar) */
    .c14-row-swipe-actions {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        background: rgba(15, 23, 42, 0.96);
        border: 2px solid #38bdf8;
        padding: 4px 10px;
        border-radius: 99px;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.45);
        margin-top: 4px;
    }
    :root.light-theme .c14-row-swipe-actions {
        background: #ffffff !important;
        border: 2px solid #000000 !important;
        color: #000000 !important;
    }

    /* الطباعة الموزونة المباشرة للشاشة عند استدعاء Print */
    @media print {
        #split-invoice-view {
            width: 100% !important;
            max-width: 100% !important;
            margin: 0 !important;
            padding: 0 !important;
        }
        #split-invoice-view table.pos-grid {
            width: 100% !important;
            border-collapse: collapse !important;
            page-break-inside: auto !important;
        }
        #split-invoice-view table.pos-grid tr {
            page-break-inside: avoid !important;
            page-break-after: auto !important;
        }
    }
</style>

<script id="split-constitution14-reports-mobile-engine">
(function() {
    if (window.__SPLIT_CONSTITUTION14_LOCK__) return;
    window.__SPLIT_CONSTITUTION14_LOCK__ = true;

    // 1. التقرير العالمي وكشف حساب وتاريخ عمليات التقسيم (مع فلاتر البرق + رصيد أول المدة + الرصيد التراكمي المتحرك + Drill-Down بضغطة زر)
    window.openSplitGlobalLedgerReportModal = function() {
        let modal = document.getElementById('split-global-ledger-report-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-global-ledger-report-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.88); z-index:999982; align-items:center; justify-content:center; padding:14px;';
            document.body.appendChild(modal);
        }
        const today = new Date().toISOString().slice(0, 10);
        const monthStart = today.slice(0, 8) + '01';
        modal.innerHTML = `
            <div class="modal-card" style="max-width:1020px; width:100%; padding:18px; box-shadow:0 28px 70px rgba(0,0,0,0.85); max-height:92vh; overflow-y:auto;">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid rgba(56,189,248,0.45); padding-bottom:10px; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
                    <div>
                        <h3 style="margin:0; font-size:1.15rem; font-weight:900; color:#38bdf8;">📊 التقرير العالمي وكشف حساب الفواتير والأذونات المقسمة (Drill-Down)</h3>
                        <small style="color:#cbd5e1; font-weight:800;">اضغط على أي سطر في التقرير لفتح أصل الفاتورة أو الإذن كشاشة وليدة (Drill-Down) في نفس جزء الثانية</small>
                    </div>
                    <div style="display:flex; gap:6px; flex-wrap:wrap;">
                        <button type="button" onclick="window.exportSplitReportToExcel()" style="padding:6px 12px; border-radius:8px; background:rgba(16,185,129,0.2); border:2px solid #10b981; color:#6ee7b7; font-weight:900; cursor:pointer;">📗 تصدير Excel</button>
                        <button type="button" onclick="window.exportSplitReportToPdf()" style="padding:6px 12px; border-radius:8px; background:rgba(56,189,248,0.2); border:2px solid #38bdf8; color:#7dd3fc; font-weight:900; cursor:pointer;">📑 طباعة A4 / PDF</button>
                        <button type="button" onclick="window.exportSplitReportToPdf(true)" style="padding:6px 12px; border-radius:8px; background:rgba(245,158,11,0.2); border:2px solid #f59e0b; color:#fde68a; font-weight:900; cursor:pointer;">🧾 كاشير 80mm</button>
                        <button type="button" onclick="window.shareCurrentSplitViaWhatsApp && window.shareCurrentSplitViaWhatsApp()" style="padding:6px 12px; border-radius:8px; background:rgba(34,197,94,0.2); border:2px solid #22c55e; color:#4ade80; font-weight:900; cursor:pointer;">📲 واتساب</button>
                        <button type="button" onclick="document.getElementById('split-global-ledger-report-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:6px 12px; font-weight:900; cursor:pointer;">✕ إغلاق</button>
                    </div>
                </div>

                <!-- فلاتر البرق اللحظية (التاريخ، العميل، المخزن، الصنف، المستخدم) -->
                <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(145px, 1fr)); gap:8px; margin-bottom:12px; background:rgba(2,6,23,0.55); padding:10px; border-radius:12px; border:1.5px solid rgba(148,163,184,0.3);">
                    <div>
                        <label style="font-size:0.74rem; font-weight:900; display:block; margin-bottom:3px;">📅 من تاريخ:</label>
                        <input type="date" id="split-rep-from" value="${monthStart}" onchange="window.renderSplitGlobalLedgerRows()" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:800;">
                    </div>
                    <div>
                        <label style="font-size:0.74rem; font-weight:900; display:block; margin-bottom:3px;">📅 إلى تاريخ:</label>
                        <input type="date" id="split-rep-to" value="${today}" onchange="window.renderSplitGlobalLedgerRows()" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:800;">
                    </div>
                    <div>
                        <label style="font-size:0.74rem; font-weight:900; display:block; margin-bottom:3px;">👤 العميل / المورد:</label>
                        <input type="text" id="split-rep-cust" placeholder="بحث بالعميل..." oninput="window.renderSplitGlobalLedgerRows()" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:800;">
                    </div>
                    <div>
                        <label style="font-size:0.74rem; font-weight:900; display:block; margin-bottom:3px;">📦 الصنف / المخزن:</label>
                        <input type="text" id="split-rep-item" placeholder="بحث بالصنف أو المخزن..." oninput="window.renderSplitGlobalLedgerRows()" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:800;">
                    </div>
                    <div>
                        <label style="font-size:0.74rem; font-weight:900; display:block; margin-bottom:3px;">👨‍💼 المستخدم:</label>
                        <input type="text" id="split-rep-user" placeholder="اسم الموظف..." oninput="window.renderSplitGlobalLedgerRows()" style="width:100%; padding:5px 7px; border-radius:7px; border:1.5px solid #38bdf8; background:#020617; color:#fff; font-weight:800;">
                    </div>
                </div>

                <div id="split-rep-summary-strip" style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:10px; padding:8px 12px; border-radius:10px; background:rgba(16,185,129,0.12); border:1.5px solid #10b981; font-weight:900; font-size:0.85rem;"></div>

                <div style="overflow-x:auto;">
                    <table id="split-global-ledger-table" class="pos-grid" style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr>
                                <th style="padding:7px; text-align:right;">🧾 رقم المستند</th>
                                <th style="padding:7px; text-align:center;">📅 التاريخ</th>
                                <th style="padding:7px; text-align:right;">👤 العميل والمخزن</th>
                                <th style="padding:7px; text-align:right;">📦 الأصناف والوحدات</th>
                                <th style="padding:7px; text-align:center;">💰 قيمة المستند</th>
                                <th style="padding:7px; text-align:center;">📈 الرصيد التراكمي المتحرك</th>
                                <th style="padding:7px; text-align:center;">🔍 التعمق (Drill-Down)</th>
                            </tr>
                        </thead>
                        <tbody id="split-global-ledger-tbody"></tbody>
                    </table>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
        window.renderSplitGlobalLedgerRows();
    };

    window.getFilteredSplitLedgerData = function() {
        const fromD = (document.getElementById('split-rep-from')?.value || '').trim();
        const toD   = (document.getElementById('split-rep-to')?.value || '').trim();
        const custQ = (document.getElementById('split-rep-cust')?.value || '').trim().toLowerCase();
        const itemQ = (document.getElementById('split-rep-item')?.value || '').trim().toLowerCase();
        const userQ = (document.getElementById('split-rep-user')?.value || '').trim().toLowerCase();

        let allSales = [];
        try { allSales = JSON.parse(localStorage.getItem('erp_sales_invoices_v1') || '[]') || []; } catch (e) {}
        if (!allSales.length && window.activeSplitInvoice) {
            allSales = [window.activeSplitInvoice];
        }

        let openingBalance = 0;
        const matched = [];

        allSales.forEach(function(inv) {
            if (inv.deleted && !inv.wasSplit) return;
            const d = String(inv.date || (inv.timestamp ? inv.timestamp.slice(0, 10) : new Date().toISOString().slice(0, 10))).slice(0, 10);
            const val = parseFloat(inv.grandTotal || inv.total || 0) || 0;
            const cName = String(inv.customerName || 'عميل نقدي');
            const wh = String(inv.warehouseName || 'المخزن الرئيسي');
            const uName = String(inv.createdByName || inv.splitByName || 'المسؤول');
            const itemsStr = (inv.items || []).map(function(it) { return (it.name || it.itemName || '') + ' (' + (it.qty ?? it.quantity ?? 0) + ')'; }).join(' ، ');

            if (fromD && d < fromD) {
                if (!inv.wasSplit) openingBalance += val;
                return;
            }
            if (toD && d > toD) return;
            if (custQ && cName.toLowerCase().indexOf(custQ) === -1) return;
            if (itemQ && itemsStr.toLowerCase().indexOf(itemQ) === -1 && wh.toLowerCase().indexOf(itemQ) === -1) return;
            if (userQ && uName.toLowerCase().indexOf(userQ) === -1) return;

            matched.push({
                inv: inv,
                invoiceNo: String(inv.invoiceNo || inv.id || ''),
                date: d,
                customerName: cName,
                warehouseName: wh,
                userName: uName,
                itemsSummary: itemsStr || '—',
                amount: val,
                currency: inv.currency || 'SDG'
            });
        });

        let runningBalance = openingBalance;
        matched.forEach(function(row) {
            runningBalance = +(runningBalance + row.amount).toFixed(2);
            row.runningBalance = runningBalance;
        });

        return { openingBalance: +openingBalance.toFixed(2), rows: matched, closingBalance: +runningBalance.toFixed(2) };
    };

    window.renderSplitGlobalLedgerRows = function() {
        const tbody = document.getElementById('split-global-ledger-tbody');
        const strip = document.getElementById('split-rep-summary-strip');
        if (!tbody) return;
        const data = window.getFilteredSplitLedgerData();

        if (strip) {
            strip.innerHTML = `
                <span>🏁 رصيد أول المدة: <strong style="color:#38bdf8; font-family:monospace;">${data.openingBalance.toLocaleString()}</strong></span>
                <span>📊 عدد المستندات المطابقة: <strong style="color:#fde047; font-family:monospace;">${data.rows.length}</strong></span>
                <span>💰 الرصيد التراكمي الختامي: <strong style="color:#6ee7b7; font-family:monospace; font-size:1rem;">${data.closingBalance.toLocaleString()} SDG</strong></span>
            `;
        }

        const openingRowHtml = `
            <tr style="background:rgba(56,189,248,0.12) !important; font-weight:900;">
                <td colspan="4" style="padding:7px; text-align:right; color:#38bdf8;">🏁 رصيد أول المدة قبل الفترة المحددة</td>
                <td style="padding:7px; text-align:center; font-family:monospace;">—</td>
                <td style="padding:7px; text-align:center; font-family:monospace; color:#38bdf8; font-weight:900;">${data.openingBalance.toLocaleString()}</td>
                <td style="padding:7px; text-align:center;">—</td>
            </tr>
        `;

        const rowsHtml = data.rows.slice(0, 80).map(function(r) {
            const escNo = r.invoiceNo.replace(/'/g, "\\'");
            return `
                <tr onclick="window.drillDownToSplitVoucherDetails('${escNo}')" style="cursor:pointer;" title="اضغط للتعمق (Drill-Down) وفتح أصل الفاتورة أو الإذن">
                    <td style="padding:7px; font-family:monospace; font-weight:900; color:#38bdf8;">#${r.invoiceNo}</td>
                    <td style="padding:7px; text-align:center; font-family:monospace; font-weight:800;">${r.date}</td>
                    <td style="padding:7px; font-weight:900;">${r.customerName}<br><small style="color:#94a3b8;">${r.warehouseName} • ${r.userName}</small></td>
                    <td style="padding:7px; font-size:0.8rem; font-weight:800;">${r.itemsSummary}</td>
                    <td style="padding:7px; text-align:center; font-family:monospace; font-weight:900; color:#fcd34d;">${r.amount.toLocaleString()} ${r.currency}</td>
                    <td style="padding:7px; text-align:center; font-family:monospace; font-weight:900; color:#6ee7b7;">${r.runningBalance.toLocaleString()}</td>
                    <td style="padding:7px; text-align:center;">
                        <button type="button" onclick="event.stopPropagation(); window.drillDownToSplitVoucherDetails('${escNo}')" style="padding:3px 9px; border-radius:7px; font-size:0.74rem; background:rgba(56,189,248,0.2); border:1.5px solid #38bdf8; color:#7dd3fc; font-weight:900; cursor:pointer;">🔍 فتح الأصل</button>
                    </td>
                </tr>
            `;
        }).join('');

        tbody.innerHTML = openingRowHtml + (rowsHtml || `<tr><td colspan="7" style="padding:12px; text-align:center; font-weight:800; color:#94a3b8;">لا توجد حركات مطابقة للفلاتر الحالية</td></tr>`);
    };

    // 2. التعمق بضغطة زر (One-Click Drill-Down Modal) لفتح أصل الفاتورة أو السند كشاشة وليدة بنفس السمة وسُمك الحواف (+2)
    window.drillDownToSplitVoucherDetails = function(invoiceNo) {
        let allSales = [];
        try { allSales = JSON.parse(localStorage.getItem('erp_sales_invoices_v1') || '[]') || []; } catch (e) {}
        const inv = allSales.find(function(x) { return String(x.invoiceNo || x.id) === String(invoiceNo); }) || window.activeSplitInvoice;
        if (!inv) {
            if (typeof showToast === 'function') showToast('ℹ️ لم يتم العثور على تفاصيل المستند #' + invoiceNo, 'info');
            return;
        }
        let modal = document.getElementById('split-drilldown-voucher-modal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'split-drilldown-voucher-modal';
            modal.className = 'modal-overlay';
            modal.style.cssText = 'display:none; position:fixed; inset:0; background:rgba(2,6,23,0.86); z-index:999988; align-items:center; justify-content:center; padding:16px;';
            document.body.appendChild(modal);
        }
        const escNo = String(inv.invoiceNo || inv.id || '').replace(/'/g, "\\'");
        const itemsRows = (inv.items || []).map(function(it, idx) {
            const m = window.resolveSplitItemUnitMeta ? window.resolveSplitItemUnitMeta(it) : { name: it.name || 'صنف', primaryUnit: it.unit || 'وحدة', price: it.price || 0 };
            const q = parseFloat(it.qty ?? it.quantity ?? 0) || 0;
            return `
                <tr>
                    <td style="padding:6px; text-align:center; font-weight:900;">${idx + 1}</td>
                    <td style="padding:6px; font-weight:900;">${m.name}</td>
                    <td style="padding:6px; text-align:center; font-family:monospace; font-weight:900; color:#38bdf8;">${q} ${m.primaryUnit}</td>
                    <td style="padding:6px; text-align:center; font-family:monospace; font-weight:900;">${m.price.toLocaleString()}</td>
                    <td style="padding:6px; text-align:center; font-family:monospace; font-weight:900; color:#10b981;">${(q * m.price).toLocaleString()}</td>
                </tr>
            `;
        }).join('');

        modal.innerHTML = `
            <div class="modal-card" style="max-width:680px; width:100%; padding:20px; box-shadow:0 28px 70px rgba(0,0,0,0.88);">
                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #38bdf8; padding-bottom:8px; margin-bottom:12px;">
                    <h3 style="margin:0; font-size:1.12rem; font-weight:900; color:#38bdf8;">🔍 التعمق في أصل المستند (Drill-Down): #${inv.invoiceNo || inv.id}</h3>
                    <button type="button" onclick="document.getElementById('split-drilldown-voucher-modal').style.display='none'" style="background:rgba(239,68,68,0.2); border:2px solid #ef4444; color:#fca5a5; border-radius:8px; padding:4px 12px; font-weight:900; cursor:pointer;">✕</button>
                </div>
                <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:8px; margin-bottom:12px; font-size:0.85rem; font-weight:900;">
                    <div>👤 العميل: <strong style="color:#fde047;">${inv.customerName || 'عميل نقدي'}</strong></div>
                    <div>📅 التاريخ: <strong style="font-family:monospace;">${inv.date || '—'}</strong></div>
                    <div>💰 الصافي: <strong style="color:#10b981; font-family:monospace;">${(parseFloat(inv.grandTotal || inv.total || 0)).toLocaleString()} ${inv.currency || 'SDG'}</strong></div>
                </div>
                <table class="pos-grid" style="width:100%; border-collapse:collapse; margin-bottom:14px;">
                    <thead>
                        <tr>
                            <th style="padding:6px;">#</th>
                            <th style="padding:6px; text-align:right;">الصنف</th>
                            <th style="padding:6px;">الكمية</th>
                            <th style="padding:6px;">السعر</th>
                            <th style="padding:6px;">الإجمالي</th>
                        </tr>
                    </thead>
                    <tbody>${itemsRows}</tbody>
                </table>
                <div style="display:flex; justify-content:flex-end; gap:8px; flex-wrap:wrap;">
                    <button type="button" onclick="document.getElementById('split-drilldown-voucher-modal').style.display='none'; document.getElementById('split-global-ledger-report-modal') && (document.getElementById('split-global-ledger-report-modal').style.display='none'); if(typeof prepareInvoiceForSplit==='function') prepareInvoiceForSplit('${escNo}');" style="padding:7px 16px; border-radius:9px; background:linear-gradient(135deg,#10b981,#059669); border:2px solid #34d399; color:#fff; font-weight:900; cursor:pointer;">✂️ فتح في لوحة التقسيم</button>
                    <button type="button" onclick="if(typeof window.openSplitGenealogyModal==='function') window.openSplitGenealogyModal('${escNo}');" style="padding:7px 14px; border-radius:9px; background:rgba(236,72,153,0.2); border:2px solid #ec4899; color:#fbcfe8; font-weight:900; cursor:pointer;">🌳 شجرة عائلة الإذن</button>
                </div>
            </div>
        `;
        modal.style.display = 'flex';
    };

    // 3. التصدير الفوري النظيف إلى Excel (CSV UTF-8 BOM) و PDF (A4 / 80mm)
    window.exportSplitReportToExcel = function() {
        const data = window.getFilteredSplitLedgerData();
        const lines = [
            ['رقم المستند', 'التاريخ', 'العميل', 'المخزن', 'الموظف', 'الأصناف', 'المبلغ', 'العملة', 'الرصيد التراكمي'].join(',')
        ];
        data.rows.forEach(function(r) {
            const esc = function(v) { return '"' + String(v ?? '').replace(/"/g, '""') + '"'; };
            lines.push([
                esc(r.invoiceNo),
                esc(r.date),
                esc(r.customerName),
                esc(r.warehouseName),
                esc(r.userName),
                esc(r.itemsSummary),
                r.amount,
                esc(r.currency),
                r.runningBalance
            ].join(','));
        });
        const csvContent = '\uFEFF' + lines.join('\r\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'كشف_تقسيم_الفواتير_' + new Date().toISOString().slice(0, 10) + '.csv';
        document.body.appendChild(a);
        a.click();
        setTimeout(function() { document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
        if (typeof showToast === 'function') showToast('📗 تم تصدير التقرير النظيف إلى Excel بنجاح', 'success');
    };

    window.exportSplitReportToPdf = function(isThermal80mm) {
        const data = window.getFilteredSplitLedgerData();
        const w = window.open('', '_blank', 'width=920,height=760');
        if (!w) return;
        const rowsHtml = data.rows.map(function(r, i) {
            return `<tr>
                <td style="padding:6px; border:1px solid #000; text-align:center;">${i + 1}</td>
                <td style="padding:6px; border:1px solid #000; font-family:monospace; font-weight:900;">#${r.invoiceNo}</td>
                <td style="padding:6px; border:1px solid #000; text-align:center;">${r.date}</td>
                <td style="padding:6px; border:1px solid #000; font-weight:800;">${r.customerName}</td>
                <td style="padding:6px; border:1px solid #000; text-align:center; font-weight:900;">${r.amount.toLocaleString()}</td>
                <td style="padding:6px; border:1px solid #000; text-align:center; font-weight:900;">${r.runningBalance.toLocaleString()}</td>
            </tr>`;
        }).join('');
        w.document.write(`<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><title>تقرير كشف تقسيم الفواتير</title>
            <style>
                @page { size: ${isThermal80mm ? '80mm auto' : 'A4 portrait'}; margin: ${isThermal80mm ? '3mm' : '10mm'}; }
                body { font-family: 'Cairo', 'Tajawal', sans-serif; color:#000; max-width: ${isThermal80mm ? '76mm' : '210mm'}; margin:0 auto; font-size: ${isThermal80mm ? '10.5px' : '13px'}; }
                table { width:100%; border-collapse:collapse; margin-top:10px; }
            </style></head><body>
            <h2 style="margin:0 0 6px; text-align:center;">📊 كشف حركة تقسيم الفواتير والأذونات</h2>
            <div style="text-align:center; font-weight:800; margin-bottom:8px;">رصيد أول المدة: ${data.openingBalance.toLocaleString()} | الرصيد الختامي التراكمي: ${data.closingBalance.toLocaleString()} SDG</div>
            <table>
                <thead><tr style="background:#e2e8f0;"><th style="padding:6px; border:1px solid #000;">#</th><th style="padding:6px; border:1px solid #000;">المستند</th><th style="padding:6px; border:1px solid #000;">التاريخ</th><th style="padding:6px; border:1px solid #000;">العميل</th><th style="padding:6px; border:1px solid #000;">المبلغ</th><th style="padding:6px; border:1px solid #000;">التراكمي</th></tr></thead>
                <tbody>${rowsHtml}</tbody>
            </table>
            <script>window.onload = function(){ setTimeout(function(){ window.print(); }, 300); };<\/script>
            <\/body><\/html>`);
        w.document.close();
    };

    // 4. حصر إيماءات الجوال في 3 حركات أساسية بسيطة فقط (Touch Gesture Trinity: Edge Swipe to Return, Pull Down to Dismiss, Row Swipe for Actions)
    let touchStartX = 0, touchStartY = 0, touchStartTarget = null;
    document.addEventListener('touchstart', function(e) {
        if (!e.touches || e.touches.length !== 1) return; // منع أي إيماءات متعددة الأصابع معقدة
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
        touchStartTarget = e.target;
    }, { passive: true });

    document.addEventListener('touchend', function(e) {
        if (!e.changedTouches || e.changedTouches.length !== 1) return;
        const splitView = document.getElementById('split-invoice-view');
        if (!splitView || splitView.style.display === 'none') return;

        const dx = e.changedTouches[0].clientX - touchStartX;
        const dy = e.changedTouches[0].clientY - touchStartY;

        // الحركة (1): السحب من الحافة للرجوع (Edge Swipe to Return)
        if ((touchStartX < 28 || touchStartX > window.innerWidth - 28) && Math.abs(dx) > 85 && Math.abs(dy) < 45) {
            if (navigator.vibrate) try { navigator.vibrate(15); } catch (err) {}
            if (window.activeSplitInvoice && typeof cancelCurrentSplit === 'function') {
                cancelCurrentSplit();
            } else if (typeof showSalesHub === 'function') {
                showSalesHub();
            }
            return;
        }

        // الحركة (2): السحب للأسفل لإغلاق النافذة الوليدة (Pull Down to Dismiss Modal)
        const openModalCard = touchStartTarget && touchStartTarget.closest && touchStartTarget.closest('.modal-overlay .modal-card');
        if (openModalCard && dy > 85 && Math.abs(dx) < 55) {
            const overlay = openModalCard.closest('.modal-overlay');
            if (overlay && overlay.id !== 'split-idle-pin-lock-overlay') {
                if (navigator.vibrate) try { navigator.vibrate(12); } catch (err) {}
                overlay.style.display = 'none';
                return;
            }
        }

        // الحركة (3): سحب الصف لإجراءات القائمة السريعة (Row Swipe for Actions)
        const rowEl = touchStartTarget && touchStartTarget.closest && touchStartTarget.closest('#split-items-body tr, #split-invoices-body tr');
        if (rowEl && Math.abs(dx) > 75 && Math.abs(dy) < 40) {
            if (navigator.vibrate) try { navigator.vibrate(12); } catch (err) {}
            const existingBar = rowEl.querySelector('.c14-row-swipe-actions');
            if (existingBar) {
                existingBar.remove();
            } else {
                const firstTd = rowEl.querySelector('td');
                if (firstTd) {
                    const bar = document.createElement('div');
                    bar.className = 'c14-row-swipe-actions';
                    bar.innerHTML = `
                        <button type="button" onclick="window.distributeSplitEqually && window.distributeSplitEqually()" style="padding:2px 8px; font-size:0.72rem; border-radius:6px; background:#0ea5e9; color:#fff; border:none; font-weight:900;">⚖️ بالتساوي</button>
                        <button type="button" onclick="window.openSplitInspectionSortingModal && window.openSplitInspectionSortingModal()" style="padding:2px 8px; font-size:0.72rem; border-radius:6px; background:#10b981; color:#fff; border:none; font-weight:900;">🔬 فحص</button>
                        <button type="button" onclick="this.parentElement.remove()" style="padding:2px 6px; font-size:0.72rem; border-radius:6px; background:#ef4444; color:#fff; border:none; font-weight:900;">✕</button>
                    `;
                    firstTd.appendChild(bar);
                }
            }
        }
    }, { passive: true });

    // 5. حارس رفع الخانة النشطة فوق كيبورد الجوال (Auto-Scroll above Mobile Virtual Keyboard)
    function scrollActiveInputAboveVirtualKeyboard(el) {
        if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'SELECT' && el.tagName !== 'TEXTAREA')) return;
        if (!el.closest || !el.closest('#split-invoice-view, .modal-overlay')) return;
        setTimeout(function() {
            try {
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            } catch (e) {}
        }, 220);
    }

    document.addEventListener('focusin', function(e) {
        if (window.innerWidth <= 920 || ('ontouchstart' in window)) {
            scrollActiveInputAboveVirtualKeyboard(e.target);
        }
    }, true);

    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', function() {
            const activeEl = document.activeElement;
            if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'SELECT')) {
                scrollActiveInputAboveVirtualKeyboard(activeEl);
            }
        });
    }
})();
</script>
