        var fmt = function(n) { return Number(n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 }); };
        var estMargin = s.grandTotal > 0 ? Math.round(s.grandTotal * 0.19) : 0;
        var creditNote = s.custDebt > 5000000
