                'treasury-vouchers.php',
                'balances_modern_hub.php',
                'journal.php',
                'trial-balance.php',
                'financial-reports.php'
            ]
        };
        try {
            localStorage.setItem('magaies_last_atomic_sync_event', JSON.stringify(payload));
            if (salesAtomicChannel) salesAtomicChannel.postMessage(payload);
